"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[5776],{54345(e){e.exports=JSON.parse('{"ko_kr":{"StarryDolls":{"success":"\uc131\uacf5","failure":"\uc2e4\ud328","action_roll":{"special":"\uc2a4\ud398\uc15c(\u3010\uc131\uba85\ub825\u3011\uc744 1D6\uc810 \ud68c\ubcf5)","fumble":"\ud38c\ube14(\ub79c\ub364\ud55c \uc0ac\uc778\uc774\u3010\uc2dd\u3011\uc73c\ub85c \ubcc0\ud654)"},"HOR":{"name":"\ub79c\ub364 \ubcc4\uc790\ub9ac\ud45c"},"HORA":{"name":"\ub79c\ub364 \ubcc4\uc790\ub9ac\ud45cA","type":"1D6","items":["\uc591\uc790\ub9ac","\ud669\uc18c\uc790\ub9ac","\uc30d\ub465\uc774\uc790\ub9ac","\uac8c\uc790\ub9ac","\uc0ac\uc790\uc790\ub9ac","\ucc98\ub140\uc790\ub9ac"]},"HORB":{"name":"\ub79c\ub364 \ubcc4\uc790\ub9ac\ud45cB","type":"1D6","items":["\ucc9c\uce6d\uc790\ub9ac","\uc804\uac08\uc790\ub9ac","\uad81\uc218\uc790\ub9ac","\uc5fc\uc18c\uc790\ub9ac","\ubb3c\ubcd1\uc790\ub9ac","\ubb3c\uace0\uae30\uc790\ub9ac"]},"RTT":{"items":[["\uc18c\uc6d0",["\ucc3d\uc870","\uc5f0\uad6c","\uc218\ud638","\uc778\uc5f0","*\uac8c\uc790\ub9ac","\uafc8","*\uc0ac\uc790\uc790\ub9ac","\uc790\uc720","\uc5f0\uc560","\uac01\uad11","\uc138\uacc4"]],["\uc6d0\uc18c",["\ube5b","\ucc9c\ub465","*\uc30d\ub465\uc774\uc790\ub9ac","\ubb3c","\ubd88\uaf43","\ubc14\ub78c","\ub098\ubb34","\uc5bc\uc74c","*\ucc98\ub140\uc790\ub9ac","\ud759","\uc5b4\ub460"]],["\ubcc4\ub2e4\ub8e8\uae30",["*\ud669\uc18c\uc790\ub9ac","\ud589\uc6b4","\ud658\uc601","\ud154\ub808\ud30c\uc2dc","\uc608\uc9c0\ubabd","\ubcc4\uc77d\uae30","\uce58\uc720","\ub0a0\uc528","\ubcc0\uc2e0","\uc2dc\uac04\uc815\uc9c0","*\ucc9c\uce6d\uc790\ub9ac"]],["\ub3d9\uc791",["*\uc591\uc790\ub9ac","\uc815\ubc00","\uace0\uc18d","\uad34\ub825","\uc740\ubc00","\ube44\ud589","\uc5b8\ub839","\ubaa8\ubc29","\uace1\uc608","\uac00\ubb34","*\uc804\uac08\uc790\ub9ac"]],["\uc18c\ud658",["\ub9ac\ubcf8","\uc870\uba85","*\ubb3c\uace0\uae30\uc790\ub9ac","\uc694\ub9ac","\uc9d0\uc2b9","\uaf43","\ud0c8\uac83","\ucc45","*\uad81\uc218\uc790\ub9ac","\ubb34\uae30","\uc7ac\ubcf4"]],["\uc778\uac04\uc131",["\uc6a9\uae30","\uc9c0\ud61c","\uc5f4\uc758","\uc870\ud654","*\ubb3c\ubcd1\uc790\ub9ac","\uc560\uc815","*\uc5fc\uc18c\uc790\ub9ac","\uc13c\uc2a4","\ub048\uae30","\uc608\uc808","\uc774\uc131"]]]},"MRT":{"name":"\uc8fc\uc778 \uad00\uacc4\ud45c","type":"1D6","items":["\ubd80\ubaa8","\uce5c\uad6c","\uc740\uc0ac","\uc9dd","\uc0c1\uc0ac","\uc560\uc778"]},"RAT":{"name":"\uad00\uacc4 \uc18d\uc131\ud45c","type":"1D6","items":["\uc874\uacbd / \uc6b0\uc6d4\uac10","\uc774\ud574 / \ubc18\ud56d","\uc720\ucf8c / \uacf5\ud3ec","\uc6b0\uc815 / \uacbd\uc7c1","\uc5f0\uc815 / \ubd88\ucf8c\uac10","\ube44\ud638 / \uc5f4\ub4f1\uac10"]},"MIR":{"name":"\uae30\uc801\ud45c","type":"1D6","items":["\ud558\ub298\uc5d0\uc11c \ub0b4\ub9ac\ub294 \ud55c \uc904\uae30 \ube5b\uc774 \ubcc4\uc778\ud615\uc758 \ubab8\uc744 \uac10\uc2f8\uace0, \uc2e0\uae30\ud55c \ud798\uc744 \uc900\ub2e4.","\uc218\ud638\uc131\uc88c\uc640 \uad00\ub828\ub41c \uc0ac\ub78c\uc774\ub098 \ub3d9\ubb3c\ub4e4\uc774 \ub098\ud0c0\ub098\uba70, \ubcc4\uc778\ud615\uc5d0\uac8c \ud798\uc744 \ube4c\ub824\uc900\ub2e4.","\uc6b4\uba85\uc774 \ubd80\uc790\uc5f0\uc2a4\ub7ec\uc6b8 \ub54c\uae4c\uc9c0 \ubcc4\uc778\ud615\uc758 \ud3b8\uc744 \ub4e4\uace0 \ubaa8\ub4e0 \uac83\uc774 \uc798 \ub418\uc5b4 \uac04\ub2e4.","\ubcc4\uc778\ud615\uc774 \ud544\uc694\ub85c \ud558\ub294 \uac83\ub4e4\uc774 \uacf5\uc911\uc5d0\uc11c \ucc28\ub840\ucc28\ub840 \ub098\ud0c0\ub09c\ub2e4.","\uc7a0\uc2dc\ub3d9\uc548 <\uadf9\uc7a5> \uac70\uc8fc\uc790\uac00 \uc815\uc2e0\uc744 \ucc28\ub9ac\uace0 \uc77c\uce58\ub2e8\uacb0\ud574 \ubcc4\uc778\ud615\uc5d0\uac8c \ud611\ub825\ud574\uc900\ub2e4.","\uc628\ubab8\uc5d0 \uc131\uba85\ub825\uc774 \ub118\uccd0\ub098\uace0, \ud55c\uacc4\ub97c \ub118\uc5b4\uc120 \ub300\uaddc\ubaa8 \uc131\uc220\uc744 \ub2e4\ub8f0 \uc218 \uc788\uac8c \ub41c\ub2e4."]},"BRT":{"name":"\uc804\uacfc\ud45c","type":"1D6","items":["\uc18c\uc9c0\ud558\uace0 \uc788\ub294 \uc544\uc774\ud15c\uc5d0\uc11c \ud558\ub098\ub97c \uc120\ud0dd\ud558\uc5ec \ub3d9\uc77c\ud55c \uac83\uc744 \ud558\ub098 \ub354 \ud68d\ub4dd\ud55c\ub2e4. \uc18c\uc9c0\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \ub2e4\uc2dc \ud55c \ubc88 \uc804\uacfc \ud45c\ub97c \uad74\ub9b0\ub2e4.","\uc2dc\uacc4\ub97c \ud68d\ub4dd\ud55c\ub2e4.","\ubb35\uc8fc\ub97c \ud68d\ub4dd\ud55c\ub2e4.","\ucf64\ud30c\uc2a4\ub97c \ud68d\ub4dd\ud55c\ub2e4.","\ubcc4\uc758 \uc870\uac01\uc744 \ud68d\ub4dd\ud55c\ub2e4.","\uc790\uc720\ub86d\uac8c \uc544\uc774\ud15c\uc744 \ud558\ub098 \ud68d\ub4dd\ud55c\ub2e4."]},"TRO":{"name":"\uc0ac\uac74\ud45c","type":"2D6","items":["\u3008\ubcc0\uc815\uccb4\u3009\ub97c \uc190\uc5d0 \uc950\uc790\ub9c8\uc790 \uc778\ud615 \ubcd1\uc0ac\uc758 \uad70\ub300\uc5d0\uac8c \ub4e4\ucf1c \ucad2\uae34\ub2e4\u2026\uc5b4\ub5bb\uac8c\ub4e0 \ubfcc\ub9ac\uce58\uc790!","\u3008\ubcc0\uc815\uccb4\u3009\ub97c \uc2ec\uc740 \ubb3c\uccb4\uac00 \ud558\ub298\uc744 \ub0a0\uace0 \uc788\ub2e4. \uc811\ucd09\ud560 \ubc29\ubc95\uc740 \uc5c6\uc744\uae4c\u2026.","\uc73c\uc2a4\uc2a4\ud55c \uc0c1\uc778\uc774 \ub098\ud0c0\ub0ac\ub2e4. \uac00\uce58 \uc788\ub294 \uac83\uc744 \ub0b4\ubc00\uba74  \u3008\ubcc0\uc815\uccb4\u3009\uc640 \uad50\ud658\ud574 \uc900\ub2e4\uace0 \ud55c\ub2e4. \ud611\uc0c1\uc744 \uc798 \ud574\ubcf4\uc790.","\u3008\ubcc0\uc815\uccb4\u3009\uc758 \uc601\ud5a5\uc73c\ub85c \uc774\uc131\uc744 \uc783\uc740 \uc0ac\ub78c\ub4e4\uc774 \ud06c\uac8c \uc2f8\uc6b0\uace0 \uc788\ub2e4. \uc774\ub7ec\uba74 \uc815\ud654\ud558\ub294 \uac83\ub3c4 \uace4\ub780\ud558\ub2e4. \ub3d9\ub8cc\uc640 \ud611\ub825\ud574 \uc911\uc7ac\ud558\uc790.","\u3008\ubcc0\uc815\uccb4\u3009\ub294 \uac74\ubb3c \uc548\uc5d0 \uc788\ub294 \uac83 \uac19\uc740\ub370 \uacbd\ube44\uac00 \uc0bc\uc5c4\ud558\ub2e4. \uc5b4\ub5bb\uac8c \ub4e4\uc5b4\uac08\uae4c\u2026.","\ubb34\uace0\ud55c \uc0ac\ub78c\ub4e4\uc774\u3008\ubcc0\uc815\uccb4\u3009\ub97c \uac00\uc9c4 \uc801\uc5d0\uac8c \uc0ac\ub85c\uc7a1\ud600 \uc788\ub2e4. \ub3d9\ub8cc\ub4e4\uacfc \ud568\uaed8\uc0ac\ub78c\ub4e4\uc744 \uad6c\ud574\ub0b4\uace0\u3008\ubcc0\uc815\uccb4\u3009\ub97c \uc815\ud654\ud558\uc790.","\u3008\ubcc0\uc815\uccb4\u3009\uc5d0 \uc870\uc885\ub2f9\ud55c \uc0ac\ub78c\ub4e4\uc774 \uc774\ucabd\uc73c\ub85c \uc801\uc758\ub97c \ubcf4\ub0b4\uace0 \uc788\ub2e4. \uc704\ud574\ub97c \uac00\ud558\uace0 \uc2f6\uc9c4 \uc54a\uc9c0\ub9cc, \uc5b4\ub5bb\uac8c \ud574\uc57c\u2026!","\u3008\ubcc0\uc815\uccb4\u3009\uc5d0 \ud640\ub9b0 \ub3d9\ubb3c\uc774 \ub3d9\ub8cc\uc5d0\uac8c \ub364\ubcbc\ub4e4\uc5c8\ub2e4! \ube68\ub9ac \uad6c\ud574\ub0b4\uc57c \ud574!","\ub3d9\ub8cc\uac00 \uc801\uc5d0\uac8c \ub0a9\uce58\ub2f9\ud558\uace0 \ub9d0\uc558\ub2e4! \uc801\uc740\u3008\ubcc0\uc815\uccb4\u3009\ub3c4 \uac00\uc9c0\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \ucd94\uc801\ud574\uc11c \ub3d9\ub8cc\ub97c \ub3d5\uc790!","\ub4a4\uc5c9\ud0a8 \uc7a5\uc18c\uc5d0\uc11c \uae38\uc744 \uc783\uace0 \ub9d0\uc558\ub2e4.\u3008\ubcc0\uc815\uccb4\u3009\uc758 \uae30\ucc99\ub3c4 \uac00\uae5d\uc9c0\ub9cc \uc5b4\ub514\uc5d0 \uc788\ub294 \uac78\uae4c?","\u3008\ubcc0\uc815\uccb4\u3009\ub294 \uae4a\uc740 \ubb3c \uc18d\uc5d0 \uc7a0\uaca8 \uc788\ub294 \uac83 \uac19\ub2e4. \uc815\ud654\ud560 \ubc29\ubc95\uc774 \uc5c6\uc744\uae4c\u2026\u2026."]},"ENC":{"name":"\uc870\uc6b0\ud45c","type":"1D6","items":["\u300e\ubcc0\uc0ac\u300f\uadc0\ub69c\ub77c\ubbf8\uc758 \ud544\ub780\ud14c\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc870\ud654\uff0f\uc778\uac04\uc1315\u300b\\n\ud6a8\uacfc: \ud50c\ub77c\ub124\ud0c0\ub9ac \uce74\ub4dc \ub8f0 \ube44\ucc44\uc6a9 \uc2dc \uc774 \uc138\uc158 \uc911\u3010\uc131\uba85\ub825\u3011\uc744 1\uc810 \uc0c1\uc2b9\uc2dc\ud0a8\ub2e4. \ud50c\ub77c\ub124\ud0c0\ub9ac \uce74\ub4dc \ub8f0 \ucc44\uc6a9 \uc2dc \ubca0\ub124\ud53d\uc744 1\ub9e4 \ud68d\ub4dd\ud55c\ub2e4","\u300e\ud56d\uacf5\uc0ac\u300f\ube44\ub458\uae30\uc758 \ucf5c\ub86c\ubcf4\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc5f4\uc758\uff0f\uc778\uac04\uc1314\u300b\\n\ud6a8\uacfc: \ucf64\ud30c\uc2a4\ub97c \ud558\ub098 \ud68d\ub4dd\ud55c\ub2e4.","\u300e\uc758\uc0ac\u300f\uae4c\ub9c8\uadc0\uc758 \ucf54\ub974\ubcf4\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc608\uc808\uff0f\uc778\uac04\uc13111\u300b\\n\ud6a8\uacfc: \ubcc4\uc758 \uc870\uac01\uc744 \ud558\ub098 \ud68d\ub4dd\ud55c\ub2e4.","\u300e\ub9c8\ubd80\u300f\uc0bd\uc0b4\uac1c\uc758 \uba54\ub3c4\ub77c\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc9c0\ud61c\uff0f\uc778\uac04\uc1313\u300b\\n\ud6a8\uacfc: \uc2dc\uacc4\ub97c \ud558\ub098 \ud68d\ub4dd\ud55c\ub2e4.","\u300e\uc5b4\ub9bf\uad11\ub300\u300f\uad11\ub300\uc758 \uc54c\ub808\ud0a4\ub178\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc13c\uc2a4\uff0f\uc778\uac04\uc1319\u300b\\n\ud6a8\uacfc: \u3010\uad00\uacc4\u3011\uc758 \uc0ac\uc6a9 \uccb4\ud06c\ub97c \ubaa8\ub450 \uc81c\uac70\ud55c\ub2e4. \uc0ac\uc6a9 \uccb4\ud06c\uac00 \uc5c6\uc744 \uacbd\uc6b0 \uc54c\ub808\ud0a4\ub178\uc640\uc758  \u3010\uad00\uacc4\u3011\ub97c \ud68d\ub4dd\ud55c\ub2e4.","\u300e\uc18c\ub140\u300f\uc5fc\uc18c\uc758 \uce74\ud504\ub808\ud2f0\ub098\\n\uc9c0\uc815\ud2b9\uae30: \u300a\uc560\uc815\uff0f\uc778\uac04\uc1317\u300b\\n\ud6a8\uacfc: \ubb35\uc8fc\ub97c \ud558\ub098 \ud68d\ub4dd\ud55c\ub2e4."]},"FWT":{"name":"\uce58\uba85\uc0c1 \ud45c","type":"1D6","items":["\uc801\uc758 \uacf5\uaca9\uc740 \ubcc4\uc778\ud615\uc758 \ub208\ub3d9\uc790\ub97c \uc9c1\uaca9\ud558\uace0 \ubcf4\uc11d\uc740 \uc120\ud608\ucc98\ub7fc \ubd80\uc11c\uc84c\ub2e4. PC\ub294 \ud615\ud574\ud654\ub41c\ub2e4.","\uc5b4\ub5bb\uac8c\ub4e0 \uce58\uba85\uc0c1\uc740 \uba74\ud588\uc9c0\ub9cc \uc774\uc81c \uc804\ud22c\ub294 \uc5b4\ub824\uc6cc \ubcf4\uc778\ub2e4\u2026PC\ub294 \uc804\ud22c\uc5d0\uc11c \ud0c8\ub77d\ud55c\ub2e4.","\ub9c8\uc9c0\ub9c9 \ud798\uc744 \uc950\uc5b4\uc9dc, \ubcc4\uc778\ud615\uc740 \ub4e4\uace0 \uc788\ub358 \uac83\uc744 \ub3d9\ub8cc\uc5d0\uac8c \ub358\uc84c\ub2e4. PC\ub294 \uc18c\uc9c0\ud55c \uc544\uc774\ud15c\uc744 \ub204\uad70\uac00\uc5d0\uac8c \uc591\ub3c4\ud55c \ub4a4 \uc804\ud22c\uc5d0\uc11c \ud0c8\ub77d\ud55c\ub2e4.","\ubcc4\uc778\ud615\uc740 \uc790\uc2e0\uc758 \ub9c8\uc74c\uc744 \ub204\uad70\uac00\uc5d0\uac8c \ub9e1\uae30\uba70 \uc9c0\uba74\uc5d0 \uc4f0\ub7ec\uc84c\ub2e4. \ub3d9\ub8cc\ub4e4 \uc911 \ub204\uad70\uac00\uac00 PC\uc5d0 \ub300\ud55c\u3010\uad00\uacc4\u3011\ub97c \ud68d\ub4dd\ud55c \ud6c4 PC\ub294 \uc804\ud22c\uc5d0\uc11c \ud0c8\ub77d\ud55c\ub2e4.","\uc774\ub300\ub85c \ub2f9\ud560 \uc218\ub294 \uc5c6\uc5b4\u2026! \ubcc4\uc778\ud615\uc740 \ubab8\uc744 \ub358\uc838 \uacf5\uaca9\ud55c\ub2e4. PC\ub294 \uc5d0\ub108\ubbf8 1\uccb4\uc5d0\uac8c \ubb34\uc7a5\uc758\u3010\ub0b4\uad6c\uce58\u3011\uc640 \uac19\uc740 \ub300\ubbf8\uc9c0\ub97c \uc900 \ud6c4, \uc804\ud22c\uc5d0\uc11c \ud0c8\ub77d\ud55c\ub2e4.","\uc774\ub7f0 \ub370\uc11c \uc4f0\ub7ec\uc9c8 \uc218\ub294 \uc5c6\ub2e4. \ubcc4\uc778\ud615\uc740\u3010\uc131\uba85\ub825\u30111\uc810\uc73c\ub85c \uc804\ud22c\uc5d0 \ubcf5\uadc0\ud55c\ub2e4. \ub2e4\uc2dc\u3010\uc131\uba85\ub825\u3011\uc774 0\uc774 \ub420 \uacbd\uc6b0 PC\ub294 \uce58\uba85\uc0c1 \ud45c\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \uc804\ud22c\uc5d0\uc11c \ud0c8\ub77d\ud55c\ub2e4."]},"CAT":{"name":"\uce74\ud0c0\uc2a4\ud2b8\ub85c\ud53c \ud45c","type":"1D6","items":["\u3008\uadf9\uc7a5\u3009 \uc804\uccb4\uac00 \ud06c\uac8c \ud754\ub4e4\ub9ac\uace0, \uacf5\uac04\uc5d0 \uade0\uc5f4\uc774 \uc0dd\uae34\ub2e4. \ud604\uc2e4\uc740 \uc0c8\ub86d\uac8c \uce60\ud574\uc838\u2026\u3008\ubcc0\uc6a9\uad6c\u3009\ub85c \ubcc0\ud588\ub2e4. \uac00\uc7a5 \ub450\ub824\uc6cc\ud588\ub358 \uc0ac\ud0dc\uc5d0 \ubcc4\uc778\ud615\ub4e4\uc740 \uba4d\ud558\ub2c8 \uc11c \uc788\uc744 \uc218\ubc16\uc5d0 \uc5c6\uc5c8\ub2e4.","\uac70\uc13c \ub545\uc6b8\ub9bc\uacfc \ud568\uaed8 \uc778\ud615\ubcd1\ub4e4\uc758 \uc99d\uc6d0\uc774 \ubc00\ub824\ub4e4\uc5b4 \ud615\uc131\uc774 \uc5ed\uc804\ub418\uace0 \ub9cc\ub2e4. \ubcc4\uc778\ud615\ub4e4\uc740 \uc5b4\uca54 \uc218 \uc5c6\uc774 <\uadf9\uc7a5>\uc744 \ub5a0\ub0ac\ub2e4.","\u300c\uc2dc\uac04\uc774 \ub2e4 \ub410\uc5b4\u300d \uc804\uc7a5\uc5d0\u3008\uc545\ub9c8\ud30c\u3009\uac00 \uc654\ub2e4. \ubcc4\uc790\ub9ac\uc758 \uac00\ud638\ub294 \ucc28\ub2e8\ub418\uace0 \ubcc4\uc778\ud615\uc758 \ubab8\uc5d0\uc11c \ud798\uc774 \ube60\uc838\ub098\uac04\ub2e4.\u300c\uc5b8\uc820\uac00 \ub2e4\uc2dc\u300d\ub77c\uace0 \ud558\ub294 \uc18c\ub9ac\ub97c \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubcc4\uc778\ud615\uc758 \uc758\uc2dd\uc740 \ub04a\uc5b4\uc9c0\uace0\u2026\ud604\uc2e4\uc138\uacc4\uc5d0\uc11c \ub208\uc744 \ub5b4\ub2e4.","\uac11\uc790\uae30 <\uad6c\ud615>\uc774 \uad34\ub85c\uc6cc\ud558\uba70 \ubab8\uc5d0 \ub0a8\uc544 \uc788\ub358 <\uc545\ubabd\uc758 \uc548\uac1c>\ub97c \ud3ed\ubc1c\uc2dc\ucf30\ub2e4. \uc758\uc2dd\uc744 \uc783\uc740 \ubcc4\uc778\ud615\ub4e4\uc774 \uae68\uc5b4\ub09c \uac83\uc740 \ud604\uc2e4 \uc138\uacc4\uc600\ub2e4. \u2026\uc544\uc9c1 \uc7ac\ub3c4\uc804\ud560 \uc2dc\uac04\uc740 \uc788\uc744 \uac83\uc774\ub2e4.","\u3008\uad6c\ud615\u3009\uc740 \uc790\uc2e0\uc744 \uc81c\uc5b4\ud560 \uc218 \uc5c6\uac8c \ub418\uc5b4,\u3008\uc545\ubabd\uc758 \uc548\uac1c\u3009\uc5d0 \ud729\uc4f8\ub824 \ubaa8\uc2b5\uc744 \uac10\ucd94\uc5b4 \ubc84\ub838\ub2e4. \uc8fc\uc778\uc744 \uc783\uc740\u3008\uadf9\uc7a5\u3009\uc740 \uc131\uc7a5\ub3c4 \uc1e0\ud1f4\ub3c4 \ud558\uc9c0 \uc54a\uc740 \ucc44, \uac70\uc6b8 \uc18d\uc5d0 \uacc4\uc18d \ub0a8\uac8c \ub420 \uac83\uc774\ub2e4.","\u3008\uad6c\ud615\u3009\uc758 \ubab8\uc740 \ud33d\ucc3d\ud558\ub294\u3008\uc545\ubabd\uc758 \uc548\uac1c\u3009\uc758 \uc555\ub825\uc744 \uacac\ub514\uc9c0 \ubabb\ud558\uace0, \uc548\ucabd\uc73c\ub85c\ubd80\ud130 \ubcf4\uc11d\uc774 \ud30c\uad34\ub418\uc5c8\ub2e4.\u3008\uad6c\ud615\u3009\uc5d0 \ub0a8\uaca8\uc9c4 \uc0dd\uba85\uc740 \uc55e\uc73c\ub85c \uc5bc\ub9c8 \ub0a8\uc9c0 \uc54a\uc558\ub2e4. \ubcc4\uc778\ud615\uc740\u3008\uad6c\ud615\u3009\uc758 \ucd5c\ud6c4\ub97c \uc9c0\ucf1c\ubcf4\uac8c \ub41c\ub2e4."]},"JDSRT":{"name":"\u3008\ub9c8\uc220\uc0ac\uc758 \uc815\uc6d0\u3009 \ud68c\uc0c1\ud45c","type":"1D6","items":["\uc77c\uc5d0 \ud544\uc694\ud55c \ub3c4\uad6c\uac00 \ubd80\uc871\ud558\uc5ec \uae09\ud788 \uc7a5\ubcf4\uae30\ub85c. \uc9d0\uc774 \ubb34\uac70\uc6cc\uc11c \ud0a4 NPC\ub3c4 \ub3c4\uc640\uc8fc\uac8c \ub418\uc5c8\ub2e4.","\ud0a4 NPC\ub294 \ub2f9\uc2e0\uc758 \uc77c\uc5d0 \uac10\uc0ac\ud558\uba70 \uc120\ubb3c\uc744 \ubcf4\ub0b4\uc8fc\uc5c8\ub2e4. \uc120\ubb3c\uc758 \ub0b4\uc6a9\ubb3c\uc740 \ud0a4 NPC\uc758 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc77c\ud488\uc778 \uac83 \uac19\ub2e4.","\uc8fc\uc778\uc740 \uc190\ub2d8\uacfc \uc774\uc57c\uae30\ud558\uace0 \uc788\ub2e4. \ub2f9\uc2e0\uc774 \ubc29 \ud55c\ucabd\uc5d0\uc11c \uc9c0\ub8e8\ud574 \ud558\uace0 \uc788\uc73c\uba74, \ud0a4 NPC\uc640 \ub208\uc774 \ub9c8\uc8fc\ucce4\ub2e4.","\uc815\ube44 \uc791\uc5c5\uc774 \uc77c\ub2e8\ub77d\ub41c \uc2dc\uc810\uc5d0\uc11c \ud0a4 NPC\uac00 \ucc28\uc640 \uacfc\uc790\ub97c \uac00\uc838\ub2e4 \uc8fc\uc5c8\ub2e4. \uc7a0\uae50 \uc26c\uc790.","\uc815\ube44 \uc911 \ubcc4\uc778\ud615\uc758 \ubab8\uc5d0\uc11c \ubc1c\uacac\ub41c \uc0c1\ucc98. \uc5b4\ub514\uc11c \ub2e4\ucce4\uc744\uae4c? \ub2f9\uc2e0\uc740 \ud0a4 NPC\uc5d0\uac8c \ubb3c\uc5b4\ubcf4\uae30\ub85c \ud588\ub2e4.","\ubc29\uc744 \uc9c0\ub098\ub358 \uc911 \uc5b4\ub5a4 \uac83\uc774 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\uac83\uc740 \ud0a4 NPC\uc5d0\uac8c \uc788\uc5b4 \ucd94\uc5b5 \uae4a\uc740 \ubb3c\uac74\uc778 \ubaa8\uc591\uc774\ub2e4."]},"SHRT":{"name":"\u3008\uc138\ube10\uc2a4 \ud5e4\ube10\u3009 \ud68c\uc0c1\ud45c","type":"1D6","items":["\uccad\uc18c\ub97c \ud558\uace0 \uc788\ub2e4 \uc9d1\uc758 \ubb3c\uac74\uc5d0 \uac78\ub824 \ub118\uc5b4\uc838 \ubd80\uc234\ubc84\ub838\ub2e4! \uac70\uae30\uc5d0 \ud0a4 NPC\uac00 \ucc3e\uc544\uc640\uc11c\u2026\u2026.","\ud0a4 NPC\ub294 \uc870\uae08 \ud53c\uace4\ud574 \ubcf4\uc778\ub2e4. \ub2f9\uc2e0\uc740 \ucc28\uc640 \uacfc\uc790\ub97c \ub4e4\uace0\uc640 \uc704\ub85c\ud574 \uc8fc\uae30\ub85c \ud588\ub2e4.","\uc694\ub9ac \uc7ac\ub8cc\ub97c \uaebc\ub0b4\uace0 \uc2f6\uc740\ub370 \uc120\ubc18\uc5d0 \uc190\uc774 \ub2ff\uc9c0 \uc54a\ub294\ub2e4\u2026\u2026. \ub2f9\uc2e0\uc740 \ud0a4 NPC\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud588\ub2e4.","\ud0a4 NPC\uc758 \uc77c\uc744 \ub3c4\uc640\uc900\ub2e4. \uc774\ub7f0 \uccb4\ud5d8\uc740 \ucc98\uc74c\uc774\uc57c! \ub2f9\uc2e0\uc740 \uc124\ub808\uba70 \ub3c4\uc804\ud55c\ub2e4.","\uc190\ub2d8\uc758 \ubcc4\uc778\ud615\uc5d0\uac8c \uc720\ub2c8\ud3fc\uc744 \ub300\uc5ec\ud574\uc8fc\uace0, \uac19\uc774 \uc0ac\uc9c4 \ucd2c\uc601\uc744 \ud55c\ub2e4. \uc465\uc2a4\ub7ec\uc6b8\uae4c? \uc544\ub2c8\uba74 \uc990\uac70\uc6b8\uae4c?","\uc624\ub298\uc740 \uc138\ube10\uc2a4 \ud5e4\ube10 \ud32c \uac10\uc0ac \uc774\ubca4\ud2b8. \ud589\uc0ac\uc7a5\uc5d0\ub294 \uac04\uc2dd\uc744 \ub4e0 \ud0a4 NPC\uc758 \ubaa8\uc2b5\ub3c4 \uc788\ub2e4."]},"BCRT":{"name":"\u3008\ucd95\ubcf5\uc758 \uc885\u3009 \ud68c\uc0c1\ud45c","type":"1D6","items":["\uc885\uc5f0 \ud6c4 \uc785\uad6c\uc5d0\uc11c \uc778\uc0ac\ub97c \ud558\ub2e4\ubcf4\uba74 \ud0a4 NPC\uac00 \ub204\uad70\uac00\uc640 \uc774\uc57c\uae30\ud558\uace0 \uc788\ub2e4. \uc0c1\ud669\uc744 \ubcf4\ub7ec \uac08\uae4c.","\ub2e4\uc74c \uacf5\uc5f0\uc744 \uc704\ud574 \uc758\uc0c1\uc744 \ub9de\ucdb0\ubcf8\ub2e4. \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ud560\uae4c? \uc758\uc0c1\uc758 \ud54f\uc740 \uc5b4\ub54c? \ud655\uc778\ud558\uace0 \uc788\uc5c8\ub294\ub370, \ud0a4 NPC\uac00 \uc0c1\ud669\uc744 \ubcf4\ub7ec \uc654\ub2e4.","\uae30\ucd08 \uc5f0\uc2b5, \uafb8\uc900\ud55c \ub8e8\ud2f4 \uc6cc\ud06c \ub3d9\uc548 \uc870\ubbf8\ub8cc\uac00 \ub418\uc5b4 \uc8fc\ub294 \uac83\uc740 \ud0a4 NPC\uc640\uc758 \uc218\ub2e4\ub2e4.","\ud559\uad50 \uacf5\uc5f0\uc774 \ub05d\ub09c \ud6c4 \uc544\uc774\ub4e4\uc5d0\uac8c \ub458\ub7ec\uc2f8\uc778\ub2e4. \ud0a4 NPC\ub294 \uc544\uc774\ub4e4\uc744 \uc88b\uc544\ud588\ub358\uac00.","\uc9c0\ubc29 \uc21c\ud68c \uacf5\uc5f0. \ud568\uaed8 \uc774\ub3d9\ud558\ub294 \ud0a4 NPC\uc640 \uc774\ub7f0\uc800\ub7f0 \uc774\uc57c\uae30\ub97c \ud558\uace0 \uc788\uc73c\uba74, \uc758\uc678\uc758 \ud654\uc81c\ub85c \uc62e\uaca8\uac00\uc11c\u2026\u2026.","\ucca0\uc218 \uc791\uc5c5\ub3c4 \ub9c9\ubc14\uc9c0\uc5d0 \uac00\uae4c\uc6cc\uc9c0\ub294 \uc2a4\ud14c\uc774\uc9c0 \uc704. \uc544\ubb34\ub3c4 \uc5c6\ub294 \uac1d\uc11d\uc744 \ud0a4 NPC\uac00 \ubc14\ub77c\ubcf4\uace0 \uc788\ub2e4."]},"ODRT":{"name":"\u3008\uc624\uba54\uac00 \ud0d0\uc815\uc0ac\u3009 \ud68c\uc0c1\ud45c","type":"1D6","items":["\uc0ac\uac74 \uc870\uc0ac\ub97c \uc704\ud574 \ud0a4 NPC\uc5d0\uac8c \ud0d0\ubb38. \uc815\ubcf4\uac00 \ub098\uc62c \uc218 \uc788\uc744\uae4c? \uc7a1\ub2f4\uc774 \ub418\uc5b4\ubc84\ub9b4\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\uc758\ub8b0\ub3c4 \uc5c6\uc774 \ud3c9\ud654\ub85c\uc6b4 \ud0d0\uc815\uc0ac\ubb34\uc18c\ub85c, \ud0a4 NPC\uac00 \uc654\ub2e4. \uc774\uac83\uc774 \uc0ac\uac74\uc758 \uc11c\ub9c9\u2026\uc774 \ub418\ub294 \uac83\uc77c\uae4c?","\ub2e4\uac19\uc774 \uc774\uc6c3\uc9d1 \uc560\uc644\ub3d9\ubb3c \ucc3e\uae30. \ud0a4 NPC\uac00 \uc54c\uace0 \uc788\ub294 \uc560\uc644\ub3d9\ubb3c\uc774\ub77c \uc870\uae08 \uac71\uc815\uc2a4\ub7ec\uc6b4 \uc5bc\uad74\uc774 \ub410\ub2e4.","\uacbd\ucc30\uc758 \uc0ac\uac74 \uc870\uc0ac\ub97c \ub3d5\ub294\ub2e4. \ud0a4 NPC\ub294 \uc0ac\uac74\uc758 \uc911\uc694 \ucc38\uace0\uc778\uc73c\ub85c \ubd88\ub824\uc9c4 \uac83 \uac19\ub2e4.","\ucc29\uc2e4\ud788 \uc7a0\ubcf5 \uc218\uc0ac\ub97c \ud558\uace0 \uc788\uc5c8\ub294\ub370 \ud0a4 NPC\uac00 \uc654\ub2e4. \ub2f9\uc2e0\uc5d0\uac8c \uc904 \uc120\ubb3c\ub3c4 \uc788\ub294 \ubaa8\uc591\uc774\ub2e4.","\ud654\ub824\ud55c \uc0ac\uac74! \uc8fc\uc778\uc758 \ucd94\ub9ac\ub97c \ub9ce\uc774 \ub3c4\uc640\uc8fc\uc5c8\ub2e4. \ud0a4 NPC\ub3c4 \ub2f9\uc2e0\uc5d0\uac8c \uacbd\uc758\ub97c \ud45c\ud55c\ub2e4."]},"SRT":{"name":"\uc885\uc790 \uad00\uacc4\ud45c","type":"1D6","items":["\uc545\uc6b0","\ud615\uc81c","\uc120\ubc30 / \ud6c4\ubc30","\uc0c1\ub2f4 \uc0c1\ub300","\ubd80\ud558 / \uac00\uc2e0","\uc30d\ub465\uc774"]},"TRS":{"name":"\uc885\uc790 \ud2b8\ub7ec\ube14\ud45c","type":"2D6","items":["\u3008\ubcc0\uc815\uccb4\u3009\ub97c \ubc1c\uacac\ud55c \uc885\uc790\ub294 \ud63c\uc790\uc11c \u300c\uc881\uc740 \uc7a5\uc18c / \ub192\uc740 \uc7a5\uc18c\u300d\uc5d0 \uac00\uc11c \ub3cc\uc544\uc62c \uc218 \uc5c6\uac8c \ub418\uc5b4 \ubc84\ub838\ub2e4. \ub3c4\uc640\uc8fc\uc790.","\ubcc4\uc778\ud615\uc758 \ud65c\uc57d\uc744 \uc9c8\ud22c\ud588\ub294\uc9c0, \uc885\uc790\uac00 \u300c\uc7a5\ub09c\uc744 \uc2dc\uc791\ud588\ub2e4 / \uc8fc\ub205\uc774 \ub4e4\uc5b4 \ubc84\ub838\ub2e4\u300d \uc6b0\uc815\uc744 \uc7ac\ud655\uc778\uc2dc\ucf1c \uc8fc\uc790.","\uc2ec\uc2ec\ud574\ud558\ub358 \uc885\uc790\ub294 \ud6cc\uca4d \uc5b4\ub514\ub860\uac00 \u300c\ub180\uc774 / \ud0d0\uc0c9\u300d\uc744 \ud558\ub7ec \uac00\ubc84\ub838\ub2e4. \uc885\uc790\uac00 \uac08\ub9cc\ud55c \uacf3\uc744 \ucc3e\uc544\ubcf4\uc790.","\uc885\uc790\uac00 \u300c\uc8fc\ubbfc / PC\u300d\uc5d0\uac8c \uccab\ub208\uc5d0 \ubc18\ud574\ubc84\ub9b0 \uac83 \uac19\uc544 \uac74\uc131\uc774\ub2e4. \ubaa8\ud5d8\uc5d0 \ud765\ubbf8\ub97c \ub3cc\ub824\uc904 \uc218\ub294 \uc5c6\uc744\uae4c.","\uc885\uc790\uc758 \ubaa8\uc2b5\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub2c8, \uad00\uc2ec\uc744 \ub048 \u300c\uc544\uc774\ub4e4/\uc791\uc740 \ub3d9\ubb3c\ub4e4\u300d\uc5d0\uac8c \ucad3\uae30\uba70 \uc11c\ub85c \ube7c\uc557\uc73c\ub824\uace0 \ud55c\ub2e4. \ub3c4\uc640\uc918\uc57c \ud55c\ub2e4!","\uc885\uc790\uac00\u3008\ubcc0\uc815\uccb4\u3009\uc5d0 \ud640\ub824 \u300c\ub0a0\ub6f0\uae30 \uc2dc\uc791\ud588\ub2e4/\ub3c4\ub9dd\ucce4\ub2e4\u300d. \uc5b4\ub5bb\uac8c\ub4e0 \uc81c\uc555\ud574 \uc815\ud654\ud558\uc790!","\uc885\uc790\ub294 \uac11\uc790\uae30 \ub3cc\uc544\uac00\uace0 \uc2f6\ub2e4\uace0 \ub9d0\ud558\uae30 \uc2dc\uc791\ud588\ub2e4. \u300c\ubcc4\uc778\ud615\uc774 \uac71\uc815\ub410\ub2e4 / \ubaa8\ud5d8\uc774 \ub450\ub824\uc6cc\uc9c4 \uac83 \uac19\ub2e4.\u300d \uc774\uc57c\uae30\ub97c \ub4e4\uc5b4\uc8fc\uc790.","\ubd80\uc8fc\uc758\ud574\uc11c\uc778\uc9c0 \uc885\uc790\uac00 \ubb34\uc5b8\uac00\ub97c \u300c\ubd80\uc154\ubc84\ub824\uc11c / \ud6d4\uccd0\ubc84\ub824\uc11c\u300d, \uc8fc\ubbfc\uc5d0\uac8c \ud63c\ub098\uace0\uc788\ub2e4. \uc911\uc7ac\ud574\uc8fc\uc790.","\uc885\uc790\uac00\u300c\ub354 \uac15\ud574\uc9c0\uace0 \uc2f6\ub2e4 / \ub354 \uc544\ub984\ub2e4\uc6cc\uc9c0\uace0 \uc2f6\ub2e4\u300d\ub77c\uace0 \uc0c1\ub2f4\ud574 \uc654\ub2e4. \uc5b4\ub5bb\uac8c \ub300\ub2f5\ud574\uc8fc\uba74 \uc88b\uc744\uae4c?","\uc885\uc790\ub294 \uc790\uc2e0\uc758 \ubab8\uc758 \uc77c\ubd80\uac00\u300c\ubd80\ub7ec\uc838\ubc84\ub9b0 \uac83\uc5d0 / \ub354\ub7ec\uc6cc\uc838\ubc84\ub9b0 \uac83\uc5d0\u300d \uce68\uc6b8\ud574 \uc788\ub294 \uac83 \uac19\ub2e4. \uace0\uccd0\uc904 \uc218\ub294 \uc5c6\uc744\uae4c?","\uc8fc\ubbfc\uc774 \uc885\uc790\ub97c \ud0d0\ub0b4 \uc5b5\uc9c0\ub85c \u300c\uceec\ub809\uc158 / \uc0c1\ud488\u300d\uc5d0 \ucd94\uac00\ud558\ub824 \ud55c\ub2e4. \ub04c\ub824\uac00\uae30 \uc804\uc5d0 \uad6c\ud574\ub0b4\uc790."]},"RAL":{"name":"\ub9ac\uc561\uc158\ud45c - \ucda9\uc131","type":"1D6","items":["\ubd84\ubd80\ub300\ub85c","\uc544\ub1e8. \uadf8\ub7f0 \uac83\uc740\u2026","\uc8fc\uc778\uc758 \ud310\ub2e8\uc740 \uc633\uc2b5\ub2c8\ub2e4","\uc5ec\uae30\ub294 \uc81c\uac8c \ub9e1\uaca8\uc8fc\uc2ed\uc2dc\uc624","\u2026\ud5db! \uc878\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4","(\uc885\uc790\uc758 \ubaa8\uc2b5)\uc758 \uae30\uc0ac\ub85c\uc11c \uc8fc\uc778\uc758 \uba85\uc744 \ub2e4\ud558\uaca0\uc2b5\ub2c8\ub2e4"]},"RAC":{"name":"\ub9ac\uc561\uc158\ud45c - \ub0c9\uc815","type":"1D6","items":["\uae30\ubd84 \ub098\uc05c \uc608\uac10\uc774 \ub4dc\ub294\uad70","\ub2f9\uc2e0\uc774 \uc5b4\ub5bb\uac8c \ud558\uace0 \uc2f6\uc740\uc9c0\uac00 \uc911\uc694\ud574","\ub098\ub294 \ubaa8\ub974\uaca0\uc5b4","\uc2e0\uacbd \uc4f8 \ud544\uc694\ub294 \uc5c6\uc5b4","\uc11c\ub450\ub974\uc790","\ub098\ub294 (\uc885\uc790\uc758 \ubaa8\uc2b5)\uc774\uc9c0\ub9cc\u2026\u2026\ub108\ub294 \uc9c4\uc815\ud55c \uce5c\uad6c\uc57c"]},"RAM":{"name":"\ub9ac\uc561\uc158\ud45c - \ubaa8\uc131","type":"1D6","items":["\uc5b4\uba38\ub098, \ubb34\uc2a8 \uc77c\uc77c\uae4c","\uba38\ub9ac\ub97c \uc4f0\ub2e4\ub4ec\uc5b4 \uc904\uac8c\uc694","\uadfc\uc0ac\ud55c \uc77c\uc774\uc5d0\uc694","\ub2f9\uc2e0\uc774 \ud558\uace0\uc2f6\uc740 \ub300\ub85c \uc88b\uc544\uc694","\uc5bc\ub9c8\ub098 \uc0ac\ub791\uc2a4\ub7ec\uc6b4 \uc544\uc774\uc778\uc9c0\uc694","(\uc885\uc790\uc758 \ubaa8\uc2b5)\uc778 \ub098\ub77c\ub3c4 \uc88b\ub2e4\uba74 \ub9ce\uc774 \uc758\uc9c0\ud574\uc918\uc694"]},"RAO":{"name":"\ub9ac\uc561\uc158\ud45c - \uc5f0\uc7a5\uc790","type":"1D6","items":["\uad1c\ucc2e\uc544, \uac71\uc815\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub3fc","\uc790\uc2e0\uc744 \ubbff\ub294 \uac70\uc57c","\ud6c4\ud6c4, \ub108\ub294 \ucc38 \uadc0\uc5fd\uad6c\ub098","\ub108\uc758 \ud798\uc740 \uc774 \uc815\ub3c4\uac00 \uc544\ub2c8\uc796\uc544?","\ub0b4\uac00 \ud560 \uc218 \uc788\ub294 \uc77c\uc740 \uadf8\ub9ac \ub9ce\uc9c0 \uc54a\ub2e8\ub2e4","(\uc885\uc790\uc758 \ubaa8\uc2b5)\uc778 \ub098\ub97c \uce5c\uad6c\ub85c \uc120\ud0dd\ud574\uc8fc\uc5b4\uc11c, \uc790\ub791\uc2a4\ub7ec\uc6cc"]},"RAI":{"name":"\ub9ac\uc561\uc158\ud45c - \ucc9c\uc9c4\ub09c\ub9cc","type":"1D6","items":["\ud574\uce58\uc6b8\uae4c~?","\uc7ac\ubc0c\uaca0\ub124!","\ub0b4\uac8c \ub9e1\uaca8\uc918!","\ub098, \uc5b4\ub824\uc6b4 \uac74 \ubab0\ub77c~","\uc788\uc796\uc544, \ub180\ub7ec\uac00\uc790~","\uadf8\ub7f0 \ub9d0\uc744 \ub4e4\uc5b4\ub3c4\u2026\u2026\ub098, (\uc885\uc790\uc758 \ubaa8\uc2b5)\uc774\ub2c8\uae4c"]},"RAE":{"name":"\ub9ac\uc561\uc158\ud45c - \uc7a5\ub85c","type":"1D6","items":["\ud5c8\ud5c8, \uae30\uc6b4\uc774 \uc88b\uad70","\uc5b4\ub514, \ub0b4\uac00 \ud574\ubcf4\uc9c0","\uc774\uac70 \uae5c\uc9dd \ub180\ub790\uad6c\ub098","\uc73c\ud760? \uc73c, \uc74c. \uadf8\ub807\uc9c0\u2026\u2026","\ub299\uc740\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uace0 \ub9cc\ub9cc\ud558\uac8c \ubcf4\uc9c0 \ub9d0\uac70\ub77c","\ub098\ub3c4 \uc624\ub7ab\ub3d9\uc548 (\uc885\uc790\uc758 \ubaa8\uc2b5)\uc744 \ud558\uace0 \uc788\uc9c0\ub9cc, \uc774\ub7f0 \uc77c\uc740 \ucc98\uc74c\uc774\ub85c\ub2e4"]},"JDSBT":{"name":"\u3008\ub9c8\uc220\uc0ac\uc758 \uc815\uc6d0\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uc815\uae30 \uc810\uac80\uc744 \uc704\ud574 \ub2e4\ub2c8\ub358 \uc870\uc9c1\uc5d0 \uc77c\uc190\uc774 \ubd80\uc871\ud574\uc838 \ud611\uc870\ub97c \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\uc8fc\uc778\uc740 \ub2f9\uc2e0\uc758 \uacbd\ud5d8\uc774 \ub420 \uac83\uc774\ub77c\uba70 \ud55c\ub3d9\uc548 \ub2e4\ub978 \uc8fc\uc778\uc758 \ubc11\uc5d0\uc11c \uc77c\ud560 \uac83\uc744 \uad8c\uc720\ud588\ub2e4.","\u300c\ubcc4\uc778\ud615\uc744 \ud30c\uacac\ud560 \uc218 \uc5c6\uaca0\ub290\ub0d0\u300d\ub294 \u3008\ub9c8\uc220\uc0ac\uc758 \uc815\uc6d0\u3009 \uce21\uc758 \uc0c1\ub2f4\uc774 \ub4e4\uc5b4\uc640, \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc73c\ub85c \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4.","\ubc14\ube60\uc11c \ubcc4\uc778\ud615 \uc810\uac80\uc5d0 \uc2dc\uac04\uc744 \ub0bc \uc218 \uc5c6\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub97c \ub300\uc2e0\ud558\uc5ec \uc7a0\uc2dc \ub2f9\uc2e0\uc774 \ubcc4\uc778\ud615\ub4e4\uc758 \uc810\uac80\uc744 \ub9e1\uac8c \ub418\uc5c8\ub2e4.","\ubab8\uc5d0 \uc704\ud654\uac10\uc744 \ub290\ub07c\ub294 \ubcc4\uc778\ud615\uc774 \uc788\ub2e4\ub294 \ub4ef \ud558\ub2e4. \uc190\uc774 \ube44\uc5b4\uc788\ub358 \ub2f9\uc2e0\uc740 \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \uc9d1\uc5d0 \uba38\ubb3c\uba70 \uc0c1\ud669\uc744 \uad00\ucc30\ud558\uac8c \ub418\uc5c8\ub2e4.","\u3008\ub9c8\uc220\uc0ac\uc758 \uc815\uc6d0\u3009\uc758 \uc5c5\ubb34\uc5d0 \uc9c0\ub8e8\ud574\uc838 \ubc84\ub9b0 \ub2f9\uc2e0\uc740 \ub2e4\ub978 \uc9c1\uc7a5\uc744 \uccb4\ud5d8\ud574 \ubcf4\uae30\ub85c \ud588\ub2e4."]},"SHBT":{"name":"\u3008\uc138\ube10\uc2a4 \ud5e4\ube10\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uc774\uc804\uc758 \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc77c\uc190 \ubd80\uc871\uc73c\ub85c \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\uc8fc\uc778\uc758 \uc9c0\uc778\uc774 \uc694\uccad\ud558\uc5ec \ub2f9\uc2e0\uc740 \ud2b9\ubcc4\ud788 \ud30c\uacac \uba54\uc774\ub4dc\ub85c \uc655\ub798\ud558\uac8c \ub418\uc5c8\ub2e4. \ud544\uc694\ud558\ub2e4\uba74 \uc5c5\ubb34\ub97c \ub3c4\uc640\uc8fc\ub294 \uc7a5\uba74\ub3c4 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\ub2f9\uc2e0\uc740 \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \ubcc4\uc778\ud615\ub4e4\uc5d0\uac8c \uc9d1\uc548\uc77c\uc744 \uac00\ub974\uce58\uae30 \uc704\ud574 \uc7a0\uc2dc \ucd9c\uc7a5\uc9c0\uc5d0 \uccb4\ub958\ud558\uac8c \ub418\uc5c8\ub2e4.","\ud074\ub77c\uc774\uc5b8\ud2b8\ub85c\ubd80\ud130 \ubcc4\uc778\ud615\uc5d0\uac8c \uc11c\ud504\ub77c\uc774\uc988 \ud30c\ud2f0\ub97c \uc5f4\uc5b4\uc8fc\uace0 \uc2f6\ub2e4\uace0 \uc0c1\ub2f4\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc5c5\ubb34\ub97c \ub3c4\uc640\uc8fc\ub294 \ucc99\ud558\uba70 \ubcc4\uc778\ud615\uc5d0 \ub300\ud55c \uc0ac\uc804 \uc870\uc0ac\ub97c \ud558\uae30\ub85c \ud588\ub2e4.","\ub2f9\uc2e0\uc758 \uba54\uc774\ub4dc \ucc28\ub9bc\uc744 \ubb34\ucc99 \uc88b\uc544\ud558\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8\ub85c\ubd80\ud130 \uc5f4\uc131\uc801\uc778 \ucd9c\uc7a5 \uc758\ub8b0\uac00 \ub4e4\uc5b4\uc654\ub2e4. \ub2f9\uc2e0\uc740 \uc2eb\uc740 \uc608\uac10\uc744 \ub290\ub07c\uba70 \ucd9c\uc7a5\uc9c0\ub85c \ud5a5\ud55c\ub2e4.","\uc5c5\ubb34 \ub2a5\ub825 \ud5a5\uc0c1\uc744 \ud558\uace0 \uc2f6\uc5c8\ub358 \ub2f9\uc2e0\uc740 \ud63c\uc790 \ucd9c\uc7a5\uc744 \ub5a0\ub098 \ub2e4\ub978 \uc8fc\uc778 \ubc11\uc5d0\uc11c \uc9d1\uc548\uc77c\uc744 \ub2f4\ub2f9\ud558\uac8c \ub418\uc5c8\ub2e4."]},"BCBT":{"name":"\u3008\ucd95\ubcf5\uc758 \uc885\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uc5b8\uc81c\ub098 \uc751\uc6d0\ud574\uc8fc\ub358 \uc870\uc9c1\uc774 \uc77c\uc190 \ubd80\uc871\uc774 \ub418\uc5b4 \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \ub2e4\uc74c \ubc30\uc5ed\uacfc \uac01\ubcf8\uc744 \uc5f0\uad6c\ud558\uae30 \uc704\ud574 \ub2e4\ub978 \uc9c1\uc7a5\uc5d0 \uba38\ubb3c\uba70 \uc77c\uc744 \uad00\ucc30\ud558\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 TV \ud504\ub85c\uadf8\ub7a8\uc774\ub098 \uc7a1\uc9c0 \ub4f1\uc758 \uae30\ud68d\uc744 \ud1b5\ud574 \ub2e4\ub978 \uc9c1\uc7a5\uc5d0\uc11c \uc9c1\uc5c5 \uccb4\ud5d8\uc744 \ud558\uac8c \ub418\uc5c8\ub2e4.","\ubcf8\ubc29\uc774 \ub2e4\uac00\uc624\uba74\uc11c \uc5f0\uc2b5 \uc2dc\uac04\uc774 \ud55c\uc2dc\ub77c\ub3c4 \uc544\uae4c\uc6cc\uc84c\ub2e4. \ub2f9\uc2e0\uc740 \uc5f0\uc2b5\uc2e4\uc5d0\uc11c \uac00\uae4c\uc6b4 \uc9c0\uc778\uc758 \uc9d1\uc5d0 \uc7a0\uc2dc \uba38\ubb34\ub974\uae30\ub85c \ud588\ub2e4.","\uadf9\ub2e8\uc758 \uad11\ud32c\uc774\ub77c\ub294 \ubcc4\uc778\ud615(\ud639\uc740 \uc8fc\uc778)\uc758 \uc5f4\ub82c\ud55c \ubd80\ud0c1\uc73c\ub85c \ub2f9\uc2e0\uc740 \uc624\ud504\uc77c \ub3d9\uc548, \ucd9c\uc7a5\uc9c0\uc5d0 \uccb4\ub958\ud558\uac8c \ub418\uc5c8\ub2e4.","\ub2e4\uc74c \uacf5\uc5f0\uae4c\uc9c0 \uc7a5\uae30 \ud734\uac00\ub97c \ubc1b\uc740 \ub2f9\uc2e0\uc740 \uae30\ubd84 \uc804\ud658\uc73c\ub85c \ub2e4\ub978 \uc8fc\uc778\uc758 \uacc1\uc5d0\uc11c \uc0dd\ud65c\ud558\uac8c \ub418\uc5c8\ub2e4."]},"ODBT":{"name":"\u3008\uc624\uba54\uac00 \ud0d0\uc815\uc0ac\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uc774\uc804\uc5d0 \uc218\uc0ac \ud611\ub825\ud574 \uc900 \uc870\uc9c1\uc774 \uc77c\uc190 \ubd80\uc871\uc774 \ub418\uc5b4 \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \uc8fc\ubcc0\uc5d0\uc11c \uc77c\uc5b4\ub098\uace0 \uc788\ub294 \uc791\uc740 \uc0ac\uac74\uc758 \ud574\uacb0\uc744 \uc758\ub8b0\ubc1b\uc544 \uccb4\ub958\ud558\uba74\uc11c \uc870\uc0ac\ud558\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \ud0c0\uac9f\uc5d0\uac8c \ub9c8\ud06c\ub418\uc9c0 \uc54a\uae30 \uc704\ud574 \ub2e4\ub978 \uc8fc\uc778\uc774 \uc18c\uc9c0\ud55c \ubcc4\uc778\ud615\uc744 \uc5f0\uae30\ud558\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc758 \uc9c1\uac10\uc740 \ucd9c\uc7a5\uc9c0\uc758 \uc8fc\uc778\uc774\ub098 \ubcc4\uc778\ud615\uc774 \uc218\uc0c1\ud558\ub2e4\uace0 \ub9d0\ud558\uace0 \uc788\ub2e4\u22ef\u22ef! \ub2f9\uc2e0\uc740 \uc7a0\uc785\ud558\uc5ec \uc870\uc0ac\ub97c \ud558\uae30\ub85c \ud588\ub2e4.","\ub2f9\uc2e0\uc740 \uc218\uc0ac\ub97c \uc704\ud574 \uc0ac\uac74 \ud604\uc7a5\uc5d0\uc11c \uac00\uae4c\uc6b4 \ub2e4\ub978 \uc8fc\uc778\uc758 \uc9d1\uc5d0 \uccb4\ub958\ud558\uac8c \ub418\uc5c8\ub2e4.","\uc758\ub8b0\uac00 \uc624\uc9c0 \uc54a\uc544\u22ef\u22ef! \ub530\ubd84\ud574\ud558\ub294 \ub2f9\uc2e0\uc744 \ubc30\ub824\ud558\uc5ec \uc8fc\uc778\uc740 \ub2f9\uc2e0\uc744 \ub2e4\ub978 \uc8fc\uc778\uc758 \uacc1\uc5d0\uc11c \ub3c4\uc640\uc8fc\ub3c4\ub85d \ud588\ub2e4."]},"ASBT":{"name":"\u3008\uc740\ud558\uc218 \uc0c1\uc810\uac00\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uac00\uac8c\uc758 \ub2e8\uace8\uc774 \uc77c\uc190 \ubd80\uc871\uc774 \ub418\uc5b4 \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\ucd9c\uc7a5\uc9c0\uc758 \uc870\uc9c1\uc774 \uc0c1\uc810\uac00\uc758 \uc774\ubca4\ud2b8\uc5d0 \ud611\ub825\ud558\uac8c \ub418\uc5c8\ub2e4. \uc0c1\ub300\ub97c \uc798 \uc54c\uc544\ub450\uace0 \uc2f6\ub2e4\uace0 \uc0dd\uac01\ud55c \ub2f9\uc2e0\uc740 \uccb4\ub958\ud558\uba74\uc11c \ud611\uc758\ub97c \uc9c4\ud589\ud558\uac8c \ub418\uc5c8\ub2e4.","\uc2e0\uc0c1\ud488\uc774\ub098 \uc0c8\ub85c\uc6b4 \uc11c\ube44\uc2a4\uc758 \uc544\uc774\ub514\uc5b4\ub97c \uc5bb\uae30 \uc704\ud574 \ub2f9\uc2e0\uc740 \ub2e4\ub978 \uc870\uc9c1\uc73c\ub85c \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4.","\uc774\uc804\uc5d0 \ucd9c\uc7a5\uc744 \uc640\uc900 \ub2f5\ub840\ub85c \uc774\ubc88\uc5d0\ub294 \ub2f9\uc2e0\uc774 \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4. \uc5f4\uc2ec\ud788 \uc77c\ud574\uc11c \uc740\ud61c\ub97c \uac1a\uc790.","\uc810\ud3ec\uc758 \ub9ac\ub274\uc5bc \uacf5\uc0ac\ub85c \uc778\ud574 \uac00\uac8c\uac00 \uc7a5\uae30 \ud734\uc5c5\uc5d0 \ub4e4\uc5b4\uac14\ub2e4. \ub2f9\uc2e0\uc740 \uadf8\ub3d9\uc548 \ub2e4\ub978 \uc8fc\uc778\uc758 \uacc1\uc5d0\uc11c \uc5c5\ubb34\ub97c \ub3d5\uac8c \ub418\uc5c8\ub2e4.","\uac00\uac8c \ub2e8\uace8\uacfc \uce5c\ud574\uc9c4 \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc758 \uc8fc\uc120\uc73c\ub85c \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4. \uc990\uac70\uc6b4 \ucd94\uc5b5\uc744 \uc794\ub729 \ub9cc\ub4e4\uc790."]},"PABT":{"name":"\u3008\ud3f4\ub77c\ub9ac\uc2a4 \uc131\ud559\uc6d0\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\ud559\uae09\uc758 \uc2dc\uac04 \uac15\uc0ac\uac00 \uc77c\uc190 \ubd80\uc871\uc774 \ub418\uc5b4 \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \uc120\uc0dd\ub2d8\uc758 \ubd80\ud0c1\uc744 \ubc1b\uc544 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\uc0ac\ud68c\uacfc \uacac\ud559\uc758 \uc77c\ud658\uc73c\ub85c \ub2f9\uc2e0\uc740 \ub2e4\ub978 \uc8fc\uc778 \ubc11\uc73c\ub85c \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \ud559\uae09 \uc2e0\ubb38\uc758 \ucde8\uc7ac\ub97c \uc704\ud574 \ub2e4\ub978 \uc8fc\uc778\uc758 \uacc1\uc73c\ub85c \ucd9c\uc7a5\uc744 \uac00\uc11c \uc815\ubcf4\ub97c \ubaa8\uc73c\uac8c \ub418\uc5c8\ub2e4.","\ud559\uad50 \uc774\ubca4\ud2b8\uac00 \ub2e4\uac00\uc624\ub294\ub370 \uc900\ube44\uac00 \ub05d\ub098\uc9c0 \uc54a\uc544! \ub2f9\uc2e0\uc740 \ud559\uae09 \uce5c\uad6c\uc758 \uc9d1\uc5d0\uc11c \ud558\ub8fb\ubc24\uc744 \uba38\ubb3c\uba70 \uc900\ube44\ub97c \ud574\ub098\uac00\uac8c \ub418\uc5c8\ub2e4.","\ube44\uc815\uaddc \uac15\uc0ac\ub85c \uc628 \uc8fc\uc778\uc774 \uc2e0\uacbd \uc4f0\uc5ec \uc5b4\uca54\uc904 \ubaa8\ub974\ub294 \ub2f9\uc2e0\uc740 \uc790\uc2e0\uc758 \uc8fc\uc778\uc5d0\uac8c \ubd80\ud0c1\ud558\uc5ec \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \uad6d\ub0b4 \uc720\ud559\uc73c\ub85c \ub2e4\ub978 \ud559\uc6d0\uc5d0 \uc77c\uc2dc\uc801\uc73c\ub85c \uc804\uc785\ud558\uac8c \ub418\uc5c8\ub2e4. \uc0c8\ub85c\uc6b4 \ub9cc\ub0a8\uc5d0 \ubd80\ud480\uc5b4 \uc624\ub978 \uae30\ub300\ub97c \uc548\uace0 \ub2f9\uc2e0\uc740 \ucd9c\uc7a5\uc744 \ub5a0\ub09c\ub2e4."]},"SCBT":{"name":"\u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\uc544\ub294 \uc8fc\uc778\uc774 \uc77c\uc190 \ubd80\uc871\uc774 \ub418\uc5b4 \ub2f9\uc2e0\uc740 \uc815\uccb4\ub97c \uc228\uae34 \ucc44 \ub3c4\uc6c0\uc744 \uc8fc\ub7ec \uac00\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc774 \ub208\uc744 \ub728\ub2c8 \uadf8\uacf3\uc740 \ub0af\uc120 \uc870\uc9c1\uc774\uc5c8\ub2e4. \ubd80\uc0c1 \ub2f9\ud55c \ub2f9\uc2e0\uc744 \uc228\uaca8\uc8fc\uace0 \uc788\uc5c8\ub358 \ubaa8\uc591\uc774\ub2e4. \ub2f9\uc2e0\uc740 \uc740\ud61c\ub97c \uac1a\uae30 \uc704\ud574 \ub3c4\uc6c0\uc744 \uc8fc\uac8c \ub418\uc5c8\ub2e4.","\uc608\uc9c0\ubabd\uc744 \ud1b5\ud574 \u3008\uad6c\ud615\u3009\uc758 \ucd9c\ud604\uc744 \uc54c\uac8c \ub41c \ub2f9\uc2e0\uc740 \uafc8\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc8fc\uc778\uc758 \uacc1\uc73c\ub85c \ucd9c\uc7a5\uac00\uc11c \ucd9c\ud604\uc744 \uae30\ub2e4\ub9ac\uae30\ub85c \ud588\ub2e4.","\ub2f9\uc2e0\uc758 \uc544\uc9c0\ud2b8\uac00 \uc801\uc2b5\uc744 \ubc1b\uc558\ub2e4. \uc801\uc5d0\uac8c \uc544\uc9c0\ud2b8\uac00 \ud2b9\uc815\ub418\uc5b4 \ubc84\ub9b0 \uac83 \uac19\ub2e4. \ud589\uc801\uc744 \ucd94\uc801\ub2f9\ud558\uc9c0 \uc54a\uae30 \uc704\ud574\uc11c \ub2f9\uc2e0\uc740 \uc7a0\uc2dc\uac04 \ucd9c\uc7a5\uc744 \uac00\uac8c \ub418\uc5c8\ub2e4.","\uc774 \ubb34\ub835 \uc804\ud22c\uac00 \ub04a\uc774\uc9c0 \uc54a\ub358 \ub2f9\uc2e0\uc740 \ub2e4\ub978 \uc8fc\uc778\uc5d0\uac8c\ub85c \ucd9c\uc7a5\uc744 \uac00\uc11c \uae30\ubd84 \uc804\ud658\uc744 \ud558\ub77c\ub294 \uc9c0\uc2dc\ub97c \ubc1b\uc558\ub2e4.","\uc8fc\uc778\uc740 \u300c\uc790\uc2e0\uc774 \uc9c0\ud0a4\uace0 \uc788\ub294 \uac83\uc744 \uc798 \uc544\ub294 \uac83\ub3c4 \uc911\uc694\ud558\ub2e4\u300d\uba70 \ub2f9\uc2e0\uc5d0\uac8c \ucd9c\uc7a5\uc744 \uad8c\uc720\ud588\ub2e4."]},"TOSCBT":{"name":"\u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uc73c\ub85c\uc758 \ucd9c\uc7a5\ud45c","type":"1D6","items":["\ub2f9\uc2e0\uc758 \uc9c1\uc7a5\uc774\u3008\uad6c\ud615\u3009\uc5d0\uac8c \uc2b5\uaca9\ub2f9\ud588\ub2e4. \uc8fc\uc778\uc740 \ubd80\uc0c1\uc73c\ub85c \uc778\ud574 \uc785\uc6d0, \ub2f9\uc2e0\uc740 \uc2b5\uaca9 \ub2f9\uc2dc \uac00\uc138\ud558\ub7ec \uc628 \u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uc5d0 \ubab8\uc744 \uc228\uae30\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740\u3008\uad6c\ud615\u3009\uc744 \uc798 \uc544\ub294 \uc778\ubb3c\ub85c\uc11c \ud611\ub825\uc744 \uc694\uccad\ubc1b\uc558\ub2e4. \ud568\uaed8 \ub3d9\ub8cc\ub97c \uad6c\ucd9c\ud574\ub0b4\uc790.","\uc608\uc9c0\ubabd\uc744 \ud1b5\ud574\uc11c \ub2f9\uc2e0\uc740 \u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uc5d0 \ud611\ub825\ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4.","\ub2f9\uc2e0\uc740 \u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uc758 \uc804\ud22c\ub97c \uc6b0\uc5f0\ud788 \ubaa9\uaca9\ud558\uc5ec \ud568\uaed8 \uc2f8\uc6b0\uace0 \uc2f6\ub2e4\uace0 \ub290\uaf08\ub2e4. \uadf8\ub4e4\ucc98\ub7fc \uac15\ud574\uc9c0\uae38 \ubc14\ub7ac\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uc774 \ub098\ud0c0\ub098\uc11c \ub2f9\uc2e0\uc774 \u3008\uad6c\ud615\u3009\uc5d0\uac8c \ub178\ub824\uc9c0\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\ub824 \uc8fc\uc5c8\ub2e4. \ub2f9\ubd84\uac04\uc740 \ud568\uaed8 \ud589\ub3d9\ud558\ub294 \uac83\uc774 \uc88b\uc744 \uac83\uc774\ub2e4.","\uc77c\ucc0d\uc774 \ub2f9\uc2e0\uc740 \u3008\uc778\ud615 \uae30\uc0ac\ub2e8\u3009\uacfc \uacf5\ud22c\ub97c \ubc8c\uc600\uace0 \uc5b8\uc81c\ub4e0 \ub2e4\uc2dc \ud611\ub825\ud558\uaca0\ub2e4\uace0 \uc57d\uc18d\ud588\uc5c8\ub2e4. \uadf8 \uc57d\uc18d\uc744 \uc774\ud589\ud560 \ub54c\uac00 \uc628 \uac83 \uac19\ub2e4. \ub2f9\uc2e0\uc740 \uc8fc\uc778\uc5d0\uac8c \uc694\uccad\ud588\ub2e4."]},"TROF":{"name":"\uc232 \uc0ac\uac74\ud45c","type":"2D6","items":["<\ubcc0\uc815\uccb4>\uc5d0 \ud640\ub9b0 \uc2dd\ucda9 \uc2dd\ubb3c\uc774 \ub3d9\ub8cc\ub97c \uc0bc\ucf1c\ubc84\ub838\ub2e4. \ube68\ub9ac \ub3c4\uc640\uc57c \ud574!","<\ubcc0\uc815\uccb4>\ub294 \uc6a9\uc18c \uc18d\uc5d0 \uc7a0\uaca8 \uc788\ub294 \ub4ef\ud558\ub2e4. \uadf8\ub7ec\ub098 \uc9c1\uc811 \uc190\uc5d0 \ub123\uc73c\ub824 \ud55c\ub2e4\uba74, \ud750\ub984\uc5d0 \ud718\ub9d0\ub824 \ub098\uac08 \uc218 \uc5c6\uac8c \ub418\uace0 \ub9d0 \uac83\uc774\ub2e4.","\uc0c8\uc758 \ub465\uc9c0 \uc548\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \uc788\ub294 \uac83 \uac19\ub2e4. \uc5b4\ubbf8 \uc0c8\ub294 \uc0c8\ub07c\ub97c \uc9c0\ud0a4\ub824\uace0 \uacbd\uacc4\ud558\uace0 \uc788\ub2e4. \ub9c8\uc74c\uc774 \uc798 \uc804\ud574\uc9c0\uac8c \ud560 \uc218\ub294 \uc5c6\uc744\uae4c?","\uac70\uc554 \uc18d\uc5d0 <\ubcc0\uc815\uccb4>\uc758 \uae30\ucc99\uc774 \uc788\ub2e4\u2026. \ud30c\uad34\ud558\uc9c0 \uc54a\uc73c\uba74 \uaebc\ub0bc \uc218 \uc5c6\uc744 \uac83\uc774\ub2e4.","<\ubcc0\uc815\uccb4>\uc5d0 \ube59\uc758\ub41c \uc791\uc740 \ub3d9\ubb3c\uc774, \uad74\uc18d\uc5d0 \ub4e4\uc5b4\uac00 \ubc84\ub838\ub2e4\u2026. \uc720\uc778\ud560 \ubc29\ubc95\uc740 \uc5c6\uc744\uae4c?","<\ubcc0\uc815\uccb4>\uc5d0 \ube59\uc758\ub41c \ub3d9\ubb3c\uc774, \ub3d9\ub8cc\uc758 \uc18c\uc911\ud55c \uac83\uc744 \ud6d4\uccd0 \uac00 \ubc84\ub838\ub2e4. \ucad3\uc544\uac00\uc11c \ub418\ucc3e\uc790!","<\ubcc0\uc815\uccb4>\uc5d0 \ube59\uc758\ub41c \uc0ac\ub098\uc6b4 \ub3d9\ubb3c\uc774 \uc228\uc18c\ub9ac\ub97c \ub0b4\uace0 \uc788\ub2e4. \uae68\uc6b0\uc9c0 \uc54a\uace0 \uac00\uae4c\uc774 \ub2e4\uac00\uac08 \uc218\ub294 \uc5c6\uc744\uae4c.","<\ubcc0\uc815\uccb4>\ub97c \uac00\uc9c4 \uc778\ud615\ubcd1\ub4e4\uc774 \ube59 \ub458\ub7ec\uc549\uc544 \ubb34\uc5b8\uac00\ub97c \uc0c1\ub2f4\ud558\uace0 \uc788\ub2e4. \ub2e4\ud589\ud788 \uc0c1\ub300\ub294 \uc774\ucabd\uc744 \ub208\uce58\ucc44\uc9c0 \ubabb\ud588\ub2e4. \uc9c0\uae08\uc774\ub77c\uba74\u2026!","\ub3d9\ub8cc\uac00 \ud568\uc815\uc5d0 \ube60\uc838\ubc84\ub838\ub2e4. \uad6c\uba4d \ubc14\ub2e5\uc5d0\ub294 <\ubcc0\uc815\uccb4>\uac00 \uc788\ub294 \uac83 \uac19\ub2e4. \uad6c\ucd9c\ud558\uace0 \uc815\ud654\ud558\uc790.","\ubb3c \uc18d\uc744 \ud5e4\uc5c4\uccd0 \ub2e4\ub2c8\ub294 \ubb3c\uace0\uae30\uac00 <\ubcc0\uc815\uccb4>\ub97c \uc0bc\ud0a4\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \uc5b4\ub5bb\uac8c \uc190\uc5d0 \ub123\uc740 \uac83\uc77c\uae4c\u2026.","\uc808\ubcbd\uc5d0 \uac78\ub9b0 \ub108\ub35c\ub108\ub35c\ud55c \ud604\uc218\uad50 \uc911\uc559\uc5d0\uc11c <\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud588\ub2e4. \ud568\uc815\uc77c\uae4c. \uadf8\ub0e5 \uac00\uc9c0\ub7ec \uac04\ub2e4\uba74 \ub2e4\ub9ac\uac00 \ub5a8\uc5b4\uc838 \ubc84\ub9b4 \uac83 \uac19\uc740\ub370\u2026."]},"TROG":{"name":"\uc815\uc6d0 \uc0ac\uac74\ud45c","type":"2D6","items":["\uc2e0\uc0ac\uc758 \uc218\uc9d1\uac00\uac00 \uac00\ubc29 \uc18d\uc5d0 <\ubcc0\uc815\uccb4>\ub97c \ub123\uc5b4\uc11c \ub2e4\ub2c8\ub294 \uac83 \uac19\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uc0c1\ub300\ub97c \ud574\uce58\uc9c0 \uc54a\uace0 \uc190\uc5d0 \ub123\uace0 \uc2f6\uc740\ub370, \uc5b4\ub5bb\uac8c \ud560\uae4c.","<\ubcc0\uc815\uccb4>\ub97c \ud488\uc740 \uc774\uc911\ud615\uc774, \ub2f9\uc2e0\uc5d0\uac8c \uc220\ub798\uc7a1\uae30\ub97c \ub3c4\uc804\ud574 \uc654\ub2e4. \uc7a1\uc73c\uba74 \uc815\ud654\ud560 \uc218 \uc788\uaca0\uc9c0\ub9cc, \uacfc\uc5f0 \ub530\ub77c\uc7a1\uc744 \uc218 \uc788\uc744\uae4c\u2026?","\uc815\uc6d0\uc218\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ube59\uc758\ud558\uc5ec \ud558\ub298 \ub192\uc774 \ubed7\uc5b4\uac04\ub2e4. <\ubcc0\uc815\uccb4>\ub294 \ub098\ubb34 \ub05d\uc5d0 \uc788\ub294 \uac83 \uac19\uc740\ub370, \uac00\uc9c0\ub7ec \uac08 \uc218 \uc788\uc744\uae4c.","\ud5c8\ub9ac\ub97c \ub2e4\uccd0\ubc84\ub9b0 \ub299\uc740 \uc815\uc6d0\uc0ac\uac00 \u300c\ub300\uc2e0 \ub098\ubb34\ub97c \ubca0\uc5b4\uc900\ub2e4\uba74 <\ubcc0\uc815\uccb4>\uc758 \uc788\ub294 \uacf3\uc744 \uc54c\ub824\uc8fc\ub9c8\u300d\ub77c\uace0 \ud55c\ub2e4. \ube68\ub9ac \ub05d\ub0b4\ub294 \ubc29\ubc95\uc740\u2026.","\uc7a5\ubbf8\uc758 \uac00\uc2dc\ub85c \uce6d\uce6d \uc5bd\ud600 \uc5c4\uc911\ud788 \uc9c0\ucf1c\uc9c4 <\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud558\uc600\ub2e4. \uc548\uc804\ud788 \uc190\uc5d0 \ub123\uc744 \ubc29\ubc95\uc774 \uc788\uc744\uae4c\u2026.","\u300c\uce68\uc785\uc790\ub2e4!\u300d <\ubcc0\uc815\uccb4>\uc5d0 \ud640\ub9b0 \uc778\ud615\ubcd1\ub4e4\uc774 \ubb34\uae30\ub97c \ub4e4\uace0 \ub2f9\uc2e0\uc744 \ub36e\uce5c\ub2e4!","\uc0ac\ub098\uc6cc \ubcf4\uc774\ub294 \uacbd\ube44\uacac\uc774 \uc73c\ub974\ub801\uac70\ub9ac\uba70 \ub2f9\uc2e0\ub4e4\uc5d0\uac8c \uc801\uc758\uc758 \ub208\ube5b\uc744 \ubcf4\ub0b4\uace0 \uc788\ub2e4. <\ubcc0\uc815\uccb4>\uc5d0 \ube59\uc758\ub418\uc5b4 \uc788\ub294 \uac83 \uac19\ub2e4.","<\ubcc0\uc815\uccb4>\uc5d0 \uc510 \uaf43\uc774 \ub369\uad74\uc744 \ubed7\uc5b4, \uc77c\ud589\uc758 \ubab8\uc744 \uc625\uc8c8\ub2e4. \uaf3c\uc9dd\ub3c4 \ud560 \uc218 \uc5c6\uc9c0\ub9cc, \ud0c8\ucd9c\ud558\uc9c0 \uc54a\uc73c\uba74\u2026!","<\ubcc0\uc815\uccb4>\uac00 \ub4e4\uc5b4\uc788\ub294 \ubc8c\uc9d1\uc5d0\uc11c, \ubc8c\uc774 \uc77c\uc81c\ud788 \ub36e\uccd0 \uc628\ub2e4! \ud1b5\uc0c1\uc758 \uacf5\uaca9\uc73c\ub85c\ub294 \ud6a8\uacfc\uac00 \uc5c6\uc744 \uac83 \uac19\uc740\ub370, \ubb54\uac00 \ubc29\ubc95\uc740 \uc5c6\uc744\uae4c?","\uc810\uc796\uc740 \uc5ec\uc131\uc774 \uc758\uc0c1\uc758 \ud750\ud2b8\ub7ec\uc9d0\uc744 \uc2e0\uacbd \uc4f0\uace0 \uc788\ub2e4. \uc218\uc120\ud560 \uc218 \uc788\uc73c\uba74 <\ubcc0\uc815\uccb4>\uc758 \uc788\ub294 \uacf3\uc744 \uac00\ub974\uccd0\uc8fc\ub294 \uac83 \uac19\ub2e4.","\uc18c\uac01\ub85c \uc548\uc5d0\uc11c <\ubcc0\uc815\uccb4>\uac00 \ud65c\ud65c \ud0c0\uc624\ub974\uba70, \uc8fc\ubcc0\uc5d0 <\uc545\ubabd\uc758 \uc548\uac1c>\ub97c \ud769\ubfcc\ub9ac\uace0 \uc788\ub2e4. \uc774 \uac70\uc13c \ubd88\uae38\uc744 \uba48\ucd94\uc9c0 \uc54a\uc73c\uba74 \uc815\ud654\ub294 \uac00\ub2a5\ud560 \uac83 \uac19\uc9c0 \uc54a\ub2e4."]},"TROC":{"name":"\uc131\ub0b4 \uc0ac\uac74\ud45c","type":"2D6","items":["\u300c\ub2f9\uc2e0\uc740 \uc655(\ub610\ub294 \uacf5\uc8fc)\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\uae4c?\u300d \uc5ec\uc790\uac00 \ub2f9\uc2e0\uc5d0\uac8c \ubb3b\ub294\ub2e4. \ub2f9\uc2e0\uc774 \ud798\uc744 \ubcf4\uc5ec\uc8fc\uba74 <\ubcc0\uc815\uccb4>\uc758 \uc704\uce58\ub97c \uc54c\ub824\uc904 \uac83 \uac19\ub2e4.","\ubb34\uac81\uace0 \ud070 \ud56d\uc544\ub9ac \uc18d\uc5d0\uc11c <\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud558\uc600\ub2e4. \ud56d\uc544\ub9ac\uc758 \uc785\uad6c\ub294 \uc881\uc544\uc11c \uc190\uc73c\ub85c\ub294 \ubabb \uc7a1\uc744 \uac83 \uac19\ub2e4. \uc5b4\ub5bb\uac8c \uc190\uc5d0 \ub123\uc744 \uc218 \uc788\uc744\uae4c\u2026?","\uc801\ubcd1\uc758 \ubb34\uae30 \uc7a5\uc2dd\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ubc15\ud600 \uc788\ub2e4. \uac00\ub2a5\ud55c \ud55c \uc6d0\ub9cc\ud558\uac8c \ud68c\uc218\ud558\uace0 \uc2f6\uc9c0\ub9cc\u2026.","\ucc9c\uc7a5\uc5d0 \ub9e4\ub2ec\ub9b0 \uc0f9\ub4e4\ub9ac\uc5d0\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \uac78\ub824 \uc12c\ub729\ud55c \uadf8\ub9bc\uc790\ub97c \ub4dc\ub9ac\uc6b0\uace0 \uc788\ub2e4. \uc5b4\ub5bb\uac8c \ud558\uba74 \uc190\uc774 \ub2ff\uc744 \uc218 \uc788\uc744\uae4c?","<\ucd94\ub77d\uc790>\ub97c \uaf2d \ub2ee\uc740 \uc870\uac01\uc0c1\uc744 \ubc1c\uacac\ud588\ub2e4. \uc655\uad00\uc5d0\ub294 <\ubcc0\uc815\uccb4>\uac00 \uc0ac\uc6a9\ub418\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \ud30c\uc218\uafbc\uc5d0\uac8c \ub4e4\ud0a4\uc9c0 \uc54a\uac8c \ud68c\uc218\ud558\uc790.","\ud1b5\ub85c\uc5d0 \uc7a5\uc2dd\ub418\uc5b4 \uc788\ub358 \uac11\uc637\uc774 \uac11\uc790\uae30 \uc6c0\uc9c1\uc774\uae30 \uc2dc\uc791\ud558\uba70 \ub36e\uccd0\uc654\ub2e4! <\ubcc0\uc815\uccb4>\uc5d0 \uc870\uc885\ub2f9\ud558\uace0 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4.","\uc950\uac00 <\ubcc0\uc815\uccb4>\ub97c \ubb3c\uace0 \ubcbd\uc5d0 \ub09c \uc791\uc740 \uad6c\uba4d\uc73c\ub85c \ub3c4\ub9dd\uac14\ub2e4. \uc5b4\ub5bb\uac8c \ud558\uba74 \uc7a1\uc744 \uc218 \uc788\uc744\uae4c\u2026?","\ubcbd\uc758 \ub9de\uc740\ud3b8\uc5d0\uc11c <\ubcc0\uc815\uccb4>\uc758 \uae30\uc0c9\uc774 \uc788\ub2e4. \uc5b4\ub518\uac00\uc5d0 \uc228\uaca8\uc9c4 \ud1b5\ub85c\uac00 \uc788\ub294 \uac83 \uac19\uc740\ub370, \uc5b4\ub5bb\uac8c \ud558\uba74 \ucc3e\uc744 \uc218 \uc788\uc744\uae4c.","\u300c\uc774\uac83\ubcf4\ub2e4 \ub098\uc5d0\uac8c \uc5b4\uc6b8\ub9ac\ub294 \uc7a5\uc2dd\ud488\uc744 \ucc3e\uc73c\uba74 \uad50\ud658\ud574 \uc8fc\ub9c8\u300d \uadc0\uc871 \ub0a8\uc131\uc774 \uac00\uc2b4\ud30d\uc5d0 <\ubcc0\uc815\uccb4>\uc758 \ube0c\ub85c\uce58\ub97c \ub2ec\uace0 \uc788\ub2e4.","<\ubcc0\uc815\uccb4>\uac00 \ub4e4\uc5b4\uac04 \ub300\ud3ec\uac00 \uae08\ubc29\uc774\ub77c\ub3c4 \ucc29\ud654\ud560 \uac83 \uac19\ub2e4. \ube68\ub9ac \uba48\ucd94\uc9c0 \uc54a\uc73c\uba74 \uc131\ubc16\uc758 \uc544\ub4dd\ud55c \uba3c \uacf3\uae4c\uc9c0 \ub0a0\uc544\uac00 \ubc84\ub9b0\ub2e4\u2026!","\u300c\ub3c4\uc640\uc900\ub2e4\uba74, <\ubcc0\uc815\uccb4>\uc758 \uc788\ub294 \uacf3\uc744 \uac00\ub974\uccd0 \uc904\uac8c\u300d \uc218\uac11\uacfc \uc871\uc1c4\ub97c \ucc2c \ubcc4\uc778\ud615\uc774 \ub2f9\uc2e0\uc5d0\uac8c \ud638\uc18c\ud55c\ub2e4. \uc778\ud615\ubcd1\uacfc \ub2ec\ub9ac \ubd84\uba85\ud788 \uc758\uc2dd\uc774 \uc788\ub294 \uac83 \uac19\ub2e4."]},"TROT":{"name":"\ub3c4\uc2dc \uc0ac\uac74\ud45c","type":"2D6","items":["\uc2e0\ud638\uac00 \uac11\uc790\uae30 \uc5c9\ub9dd\uc774 \ub418\uc5b4 \ud63c\ub780\uc774 \uc77c\uc5b4\ub098\uace0 \uc788\ub2e4. \uc2e0\ud638\ub4f1\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ube59\uc758\ud558\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \ud3ed\uc8fc\ud558\ub294 \ucc28\ub97c \ud5e4\uce58\uace0 \uc2e0\ud638\ub4f1\uc5d0 \ub3c4\ub2ec\ud558\uc790.","\uae38 \uc783\uc740 \uc18c\ub140\uac00 \uc6b8\uba74\uc11c\u300c\uc774\uac70 \uc904 \ud14c\ub2c8\uae4c \uc5c4\ub9c8\ud55c\ud14c \ub370\ub824\ub2e4\uc918!\u300d\ub77c\uba70 \ubb18\ud55c \ub3cc\uc744 \ub0b4\ubbfc\ub2e4. \u2026<\ubcc0\uc815\uccb4>\uac00 \uc544\ub2cc\uac00!","\u300c\uac70\uae30 \ub108, \ub098\uc05c \uad00\uc0c1\uc744 \ud558\uace0 \uc788\ub124\u300d \uc810\uc7c1\uc774 \ub178\ud30c\uc5d0\uac8c \ubd99\uc7a1\ud614\ub2e4. \uc218\uc911\uc5d0\ub294 \uc218\uc815 \ub300\uc2e0\uc5d0 <\ubcc0\uc815\uccb4>\uac00\u2026!","<\ubcc0\uc815\uccb4>\ub97c \uc2e4\uc740 \ud3ed\uc8fc \ud2b8\ub7ed\uc774 \ub2f9\uc2e0\ub4e4\uc5d0\uac8c \ub3cc\uc9c4\ud574 \uc654\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uba48\ucd94\uc9c0 \uc54a\uc73c\uba74 <\ubcc0\uc815\uccb4>\uac00 \ubaa8\ub450 \uc81c\uac01\uac01\uc73c\ub85c \ud769\uc5b4\uc9c0\uace0 \ub9d0 \uac83\uc774\ub2e4!","\uc778\ud30c \uc18d\uc5d0\uc11c <\ubcc0\uc815\uccb4>\uc758 \uae30\uc0c9\uc744 \ub290\uaf08\ub2e4. \uc774 \uc911 \ub204\uad70\uac00\uac00 \uac00\uc9c0\uace0 \uc788\uc744 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub5bb\uac8c \ucc3e\uc544\ub0bc\uae4c?","\uc5c4\uc911\ud55c \uc5f4\uc1e0\uac00 \ub2ec\ub9b0 \uc1fc\ucf00\uc774\uc2a4 \uc18d\uc5d0\uc11c <\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud588\ub2e4. \ubb54\uac00 \uc5ec\ub294 \ubc29\ubc95\uc740 \uc5c6\uc744\uae4c\u2026?","\u300c\ub0a0\uce58\uae30\uc57c!\u300d \uc5ec\uc131\uc758 \uc678\uce68\uc5d0 \uace0\uac1c\ub97c \ub4e4\uc790 <\ubcc0\uc815\uccb4>\uc5d0 \ud640\ub9b0 \ub0a8\uc131\uc774 \ub3c4\ub9dd\uac00\uace0 \uc788\ub2e4!","\uacf5\uc0ac \ucc28\ub7c9\uc758 \uc9d0\uce78\uc5d0 \uc794\ud574\uc9f8\ub85c <\ubcc0\uc815\uccb4>\uac00 \uc313\uc5ec\uc788\ub2e4. \uc6b4\ubc18\ub418\uae30 \uc804\uc5d0 \uc218\uac70\ud574\uc57c \ud558\ub294\ub370\u2026.","\ub3c4\uc2dc\uacf5\uc6d0\uc758 \ubb3c\uac00\uac00 \uac80\uace0 \ud0c1\ud558\ub2e4. \uc548\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \uac00\ub77c\uc549\uc544 \uc788\ub294 \uac83 \uac19\ub2e4. \uc798 \ucc3e\uc544\ub0bc \ubc29\ubc95\uc774 \uc5c6\uc744\uae4c?","<\ubcc0\uc815\uccb4>\ub97c \uc190\uc5d0 \ub123\uc790\ub9c8\uc790 \uae4c\ub9c8\uadc0 \ub5bc\uac00 \ub364\ubcbc\ub4e4\uc5c8\ub2e4! \ubc18\uc9dd\uac70\ub9ac\ub294 <\ubcc0\uc815\uccb4>\ub97c \ub178\ub9ac\uace0 \uc788\ub294 \uac83 \uac19\ub2e4.","\uae38\uac70\ub9ac\uc5d0\uc11c \ub0a8\uc790\ub4e4\ub07c\ub9ac \uc2f8\uc6b0\uace0 \uc788\ub294\ub370, \uc0c1\ud0dc\uac00 \uc774\uc0c1\ud558\ub2e4. \ub54c\ub9ac\ub824\ub294 \ub0a8\uc790\uc758 \uc190\uc5d0\ub294 <\ubcc0\uc815\uccb4>\uac00! \uc2f8\uc6c0\uc744 \uc911\uc7ac\ud574\uc11c <\ubcc0\uc815\uccb4>\ub97c \uc190\uc5d0 \ub123\uc790."]},"TROL":{"name":"\ub3c4\uc11c\uad00 \uc0ac\uac74\ud45c","type":"2D6","items":["\ucc45\uc7a5\uc5d0 \ub204\uad70\uac00\uc758 \uc77c\uae30\uac00 \uc11e\uc5ec \uc788\ub294 \uac83\uc744 \ubc1c\uacac\ud588\ub2e4. \uc548\uc5d0\ub294 \u300c\uc0ac\uc545\ud55c \uac80\uc740 \ubcf4\uc11d\uc744 \uc785\uc218\ud588\ub2e4\u300d\ub77c\uace0 \uc801\ud600 \uc788\ub2e4. \uc8fc\uc778\uc744 \ucc3e\uc73c\uba74, <\ubcc0\uc815\uccb4>\ub97c \uc190\uc5d0 \ub123\uc744 \uc218 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\u300c\ucc3e\uace0 \uc788\ub294 \uac83\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub294 \ucc45\u300d\uc744 \ubc1c\uacac\ud588\ub2e4. \uae00\uc528\ub3c4 \ud398\uc774\uc9c0\ub3c4 \uaf64 \ub9ce\uc740 \ucc45\uc774\uc9c0\ub9cc, <\ubcc0\uc815\uccb4>\uc758 \uc704\uce58\uac00 \uc801\ud78c \ud398\uc774\uc9c0\ub97c \ucc3e\uc744 \uc218 \uc788\uc744\uae4c\u2026?","\uad00\uc6d0\uc774 <\ubcc0\uc815\uccb4>\uac00 \uc788\ub294 \uacf3\uc744 \uac00\ub974\uccd0 \uc8fc\uc5c8\uc9c0\ub9cc, \uae38 \uc548\ub0b4\uc758 \ub0b4\uc6a9\uc774 \uc0c1\ub2f9\ud788 \ubcf5\uc7a1\ud558\ub2e4\u2026. \uc5b4\ub5bb\uac8c\ub4e0 \ub3c4\ub2ec\ud560 \ubc29\ubc95\uc740\u2026.","\ucc45\uc774 \uc313\uc5ec \uc0dd\uae34 \uac70\ub300\ud55c \ud0d1\uc5d0\uc11c, <\ubcc0\uc815\uccb4>\uc758 \uae30\uc0c9\uc774 \ub290\uaef4\uc9c4\ub2e4. \ucc45\uc744 \uc5b4\ub5bb\uac8c\ub4e0 \uce58\uc6cc\ub0bc \uc218\ub294 \uc5c6\uc744\uae4c.","\ucc45\uc5d0 \ub2ff\uc790\ub9c8\uc790 <\uc545\ubabd\uc758 \uc548\uac1c>\uac00 \ubfdc\uc5b4\uc838 \ub098\uc640 \uc2dc\uc57c\ub97c \ube7c\uc557\uae34\ub2e4. \uce84\uce84\ud574\uc11c \uc544\ubb34\uac83\ub3c4 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc, \ube68\ub9ac <\ubcc0\uc815\uccb4>\uc758 \uc601\ud5a5\uc744 \ubc1b\uc740 \ucc45\uc744 \ucc3e\uc544\ubcf4\uc790.","<\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud55c \uc9c1\ud6c4, \uac70\ub300\ud55c \ucc45\uc7a5\uc774 \uc4f0\ub7ec\uc84c\ub2e4. \uc774\ub300\ub85c\ub77c\uba74 <\ubcc0\uc815\uccb4>\ub97c \uc190\uc5d0 \ub123\uae30 \uc804\uc5d0 \ubaa8\ub450 \uae54\ub824 \ubc84\ub9b0\ub2e4\u2026!","\uadf8\ub9bc\ucc45\uc744 \ud3bc\uce58\uc790, \uc774\uc57c\uae30\uc758 \ub4f1\uc7a5\uc778\ubb3c\uc774 \ub6f0\uc5b4\ub098\uc640 \ub36e\uccd0\uc654\ub2e4. \uc0c1\ub300\ub294 <\ubcc0\uc815\uccb4>\uc5d0 \ud640\ub824 \uc788\ub294 \uac83 \uac19\ub2e4.","<\ubcc0\uc815\uccb4>\uac00 \uae43\ub4e0 \ucc45\uc744 \ub450 \uba85\uc758 \uc778\ud615\ubcd1\uc774 \uac10\uc2dc\ud558\uace0 \uc788\ub2e4. \uadf8\ub4e4\uc758 \uc8fc\uc758\ub97c \ub04c \ubc29\ubc95\uc774 \uc5c6\uc744\uae4c\u2026?","\ucc45\uc7a5 \ub9e8 \uc717\uc904\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ub07c\uc5b4 \uc788\uc9c0\ub9cc, \uc0ac\ub2e4\ub9ac \uac19\uc740 \uac83\uc740 \ucc3e\uc544\ubcfc \uc218 \uc5c6\ub2e4. \uae30\uc5b4\uc624\ub97c \uc218\ubc16\uc5d0 \uc5c6\ub294 \uac83\uc77c\uae4c\u2026?","\ub2f9\uc2e0\uc740 <\ubcc0\uc815\uccb4>\ub97c \uc190\uc5d0 \ub123\uc5c8\uc9c0\ub9cc, \uc774\uc911\ud615\uc5d0\uac8c \ube7c\uc557\uae30\uace0 \ub9cc\ub2e4. \u300c\ub0b4\uac00 \ubaa8\ub974\ub294 \uc774\uc57c\uae30\ub97c \ub4e4\ub824\uc8fc\uba74 \ub3cc\ub824\uc904\uac8c\u300d\ub77c\uace0 \uc774\uc911\ud615\uc740 \ub9d0\ud558\uc9c0\ub9cc\u2026.","\u300c\ucc45 \uc880 \uc77d\uc5b4\uc8fc\uc2dc\uaca0\uc5b4\uc694?\u300d \uc18c\ub140\ub294 <\uc545\ubabd\uc758 \uc548\uac1c>\uc5d0\uc11c \uac80\uac8c \ub179\uc740 \ucc45\uc744 \ub04c\uc5b4\uc548\uace0 \ub9d0\ud55c\ub2e4. \ubd80\ud0c1\uc744 \ub4e4\uc5b4\uc8fc\uc9c0 \ubabb\ud558\uba74 <\ubcc0\uc815\uccb4>\uac00 \uc228\uc5b4\ub4e0 \ucc45\uc740 \ub193\uc544\uc8fc\uc9c0 \uc54a\uc744 \uac83 \uac19\ub2e4."]},"TROS":{"name":"\uc5ed \uc0ac\uac74\ud45c","type":"2D6","items":["\u300c\uc5ec\ud589 \ucea0\ud398\uc778 \uc2e0\uccad\uc790\uc5d0\uac8c\ub294 <\ubcc0\uc815\uccb4>\ub97c \uc120\ubb3c!\u300d\uc774\ub77c\uace0 \uc801\ud78c \ubcbd\ubcf4\ub97c \ubc1c\uacac\ud55c\ub2e4. \ub204\uad70\uac00\uc758 \uc190\uc5d0 \ub118\uc5b4\uac00\uae30 \uc804\uc5d0 \ud68c\uc218\ud558\uc790!","\ubd84\uc2e4\ubb3c\uc744 \ucc3e\uace0 \uc788\ub294 \ub178\uc778\uc744 \ub9cc\ub09c\ub2e4. \ucc3e\uc544\uc900\ub2e4\uba74 <\ubcc0\uc815\uccb4>\uc640 \uad50\ud658\ud574 \uc8fc\ub294 \uac83 \uac19\ub2e4.","\uac1c\ucc30\uad6c \ub108\uba38\uc5d0\uc11c <\ubcc0\uc815\uccb4>\ub97c \ubc1c\uacac\ud588\uc9c0\ub9cc, \u300c\ud45c\uac00 \uc5c6\uc73c\uba74 \ud1b5\uacfc\ud560 \uc218 \uc5c6\uc5b4\uc694\u300d\ub77c\uba70 \uba48\ucdb0 \uc138\uc6cc\uc84c\ub2e4. \ud558\uc9c0\ub9cc \ub9e4\ud45c\uc18c\ub3c4 \ucc3e\uc744 \uc218 \uc5c6\uace0, \uc5b4\ub5bb\uac8c \uc9c0\ub098\uac00\uc57c \ud560\uae4c\u2026.","\uc5ec\ub7ec \ub9c8\ub9ac\uc758 \ube44\ub458\uae30\uac00 <\ubcc0\uc815\uccb4>\ub97c \ucabc\uba70 \ub180\uace0 \uc788\ub2e4. \ube44\ub458\uae30\uc5d0\uac8c <\ubcc0\uc815\uccb4>\uc758 \uc601\ud5a5\uc774 \ub098\ud0c0\ub098\uae30 \uc804\uc5d0 \ud68c\uc218\ud558\uc790.","\u300c\uc774\uac8c \ubb50\uc9c0?\u300d \uc5ed\ubb34\uc6d0\ub4e4\uc774 <\ubcc0\uc815\uccb4>\ub97c \ub458\ub7ec\uc2f8\uace0 \uace0\uac1c\ub97c \uac38\uc6b0\ub6b1\uac70\ub9ac\uace0 \uc788\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uc124\ub4dd\ud574\uc11c <\ubcc0\uc815\uccb4>\ub97c \uac74\ub124\ub2ec\ub77c\uace0 \ud558\uc790.","\uc120\ub85c \uc704\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ub5a8\uc5b4\uc838 \uc788\uc9c0\ub9cc, \uc774\uc81c \uace7 \uc5f4\ucc28\uac00 \uc628\ub2e4! \uc5f4\ucc28\uac00 \ud1b5\uacfc\ud55c \ud6c4, \uc81c\uc790\ub9ac\uc5d0 \uc788\uc744\uc9c0\ub294 \uc54c \uc218 \uc5c6\ub2e4\u2026!","<\ubcc0\uc815\uccb4>\ub97c \ub4e0 \uc778\ud615\ubcd1\ub4e4\uc774 \ub2f9\uc2e0\ub4e4\uc744 \ucad3\ub2e4\uac00, \uc778\ud30c \uc18d\uc5d0\uc11c \ub193\uccd0\ubc84\ub9b0\ub2e4. \uc774\uc6a9\uac1d\uc5d0 \uc798 \uc11e\uc5ec \ub4e0\ub2e4\uba74 \uc2f8\uc6b0\uc9c0 \uc54a\uace0 \uc815\ud654\ud560 \uc218 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\uc815\ucc28 \uc911\uc778 \uc804\ucc28\uac00 <\uc545\ubabd\uc758 \uc548\uac1c>\uc5d0 \ud729\uc2f8\uc5ec, \uc2b9\uac1d\ub4e4\uc740 \ud328\ub2c9 \uc0c1\ud0dc\uc5d0 \ube60\uc84c\ub2e4. \uc800 \uc548\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \uc788\uc744 \uac83\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc6b0\uc120 \uc2b9\uac1d\uc744 \uad6c\ucd9c\ud558\uc790.","<\ubcc0\uc815\uccb4>\ub97c \ud488\uc740 \uc774\uc911\ud615\uc774 \ub2f9\uc2e0\uc744 \uc120\ub85c\uc5d0 \ubc00\uc5b4 \ub5a8\uc5b4\ub728\ub9ac\uae30 \uc704\ud574 \ubd80\ub52a\ud600\uc654\ub2e4. \uc5b4\ub5bb\uac8c\ub4e0 \uc774 \uc0c1\ud669\uc744 \uc774\uaca8\ub0b4\uace0 \uc774\uc911\ud615\uc744 \ubd99\uc7a1\uc790!","\uc2dc\uac04\ud45c\uc5d0 <\ubcc0\uc815\uccb4> \uc5f4\ucc28\ub77c\uace0 \ud45c\uc2dc\ub41c\ub2e4. <\ubcc0\uc815\uccb4>\uc5d0 \ube59\uc758\ub41c \uc5f4\ucc28\uac00 \ud1b5\uacfc\ud558\ub294 \ub4ef\ud558\ub2e4. \uc5f4\ucc28\ub97c \uba48\ucd94\ub294 \uac83\uc740 \uac00\ub2a5\ud560\uae4c\u2026?!","\uae38\uac70\ub9ac \ucf58\uc11c\ud2b8 \uad00\uac1d\ub4e4\uc758 \ubaa8\uc2b5\uc774 \uc774\uc0c1\ud558\ub2e4. \uc790\uc138\ud788 \ubcf4\ub2c8 \uc5f0\uc8fc\uc790\uc758 \uc545\uae30\uc5d0 <\ubcc0\uc815\uccb4>\uac00 \ubc15\ud600 \uc788\ub2e4! \ube68\ub9ac \uc815\ud654\ud574\uc11c \ubaa8\ub450\uc758 \ub208\uc744 \ub728\uac8c \ub9cc\ub4e4\uc790."]}}}}')}}]);